-- ==== 20_packages/01_ie_mfcs_config.sql

-- Environment configuration lookup: one row per key in IE_MFCS_CFG_SETTING.
--
-- Everything tunable lives here - endpoints, MFCS defaults and feature
-- translations, feature flags - so behaviour changes are an update statement,
-- not a redeploy. Seeded by database/10_tables/03_config_seed.sql.

create or replace package ie_mfcs_config authid definer as
    -- Returns the enabled value for a key, or p_default when the key is absent.
    -- Callers pass the default inline, so a missing row is never an error.
    function get_config(
        p_key         in varchar2,
        p_default     in varchar2 default null,
        p_environment in varchar2 default 'DEFAULT'
    ) return varchar2;
end ie_mfcs_config;
/

create or replace package body ie_mfcs_config as
    function get_config(
        p_key         in varchar2,
        p_default     in varchar2 default null,
        p_environment in varchar2 default 'DEFAULT'
    ) return varchar2 is
        l_value varchar2(32767);
    begin
        select dbms_lob.substr(config_value, 32767, 1)
          into l_value
          from ie_mfcs_cfg_setting
         where environment = p_environment
           and config_key = p_key
           and enabled_ind = 'Y';

        return l_value;
    exception
        when no_data_found then
            return p_default;
    end;
end ie_mfcs_config;
/

-- ==== 20_packages/02_ie_mfcs_event.sql

-- Autonomous event log, and the one JSON string-escape helper.
--
-- Every package that talks to MFCS logs its progress here. The autonomous
-- transaction is the point: an event survives the rollback of the step that
-- logged it, so a failed request still tells its story. A logging failure is
-- swallowed - the log must never be the reason a request fails.

create or replace package ie_mfcs_event authid definer as
    -- Escapes a value for embedding inside a JSON string literal. Public because
    -- several packages hand-build small JSON documents (detail payloads, status
    -- responses); this is the single copy they all share. Returns null for null.
    function escape_json(p_value in varchar2) return varchar2;

    -- Appends one row to IE_MFCS_LOG_EVENT in an autonomous transaction and commits it.
    -- p_detail_payload is expected to be a JSON document; build its string
    -- values with escape_json.
    procedure log_event(
        p_action_request_id in varchar2,
        p_event_phase       in varchar2,
        p_step_code         in varchar2 default null,
        p_attempt_id        in number default null,
        p_message           in varchar2 default null,
        p_detail_payload    in clob default null,
        p_event_level       in varchar2 default 'INFO'
    );
end ie_mfcs_event;
/

create or replace package body ie_mfcs_event as
    function escape_json(p_value in varchar2) return varchar2 is
    begin
        if p_value is null then
            return null;
        end if;

        return replace(
                   replace(
                       replace(
                           replace(p_value, '\', '\\'),
                           '"', '\"'
                       ),
                       chr(10), '\n'
                   ),
                   chr(13), '\r'
               );
    end;

    procedure log_event(
        p_action_request_id in varchar2,
        p_event_phase       in varchar2,
        p_step_code         in varchar2 default null,
        p_attempt_id        in number default null,
        p_message           in varchar2 default null,
        p_detail_payload    in clob default null,
        p_event_level       in varchar2 default 'INFO'
    ) is
        pragma autonomous_transaction;
    begin
        insert into ie_mfcs_log_event (
            log_id,
            action_request_id,
            step_code,
            attempt_id,
            event_level,
            event_phase,
            message,
            detail_payload
        ) values (
            ie_mfcs_seq_event_log_id.nextval,
            p_action_request_id,
            p_step_code,
            p_attempt_id,
            coalesce(p_event_level, 'INFO'),
            p_event_phase,
            substr(p_message, 1, 1000),
            p_detail_payload
        );

        commit;
    exception
        when others then
            rollback;
    end;
end ie_mfcs_event;
/

-- ==== 20_packages/03_ie_mfcs_request.sql

-- Request lifecycle: registration, idempotency, status, generated identifiers.
--
-- A request is registered once under its ACTION_REQUEST_ID and never changes:
-- the same id with the same payload replays the stored outcome, the same id
-- with a different payload is a 409 conflict. Identifiers MFCS generates along
-- the way (style, SKU and order numbers) are recorded in IE_MFCS_MAP_ENTITY so later
-- requests naming the same source references can resolve them.

create or replace package ie_mfcs_request authid definer as
    -- SHA-256 of the payload, used to tell a replay from a conflicting reuse
    -- of the same ACTION_REQUEST_ID.
    -- The inbound document, in canonical form.
    --
    -- Callers may send SIZE_CURVE_DETAIL or the older PLMSizeCurveDtl; everything
    -- downstream sees only the former. The old name said two wrong things: it was
    -- the single camelCase key in an upper-snake document, and it named its source
    -- system in a contract that already carries SOURCE_SYSTEM as a field.
    --
    -- This runs at intake, before the payload is hashed, stored or validated, and
    -- that ordering is the point. Resume replays the *stored* payload, so a
    -- document normalised on the way in is canonical for the rest of its life; one
    -- normalised on the way out would leave both shapes in the system forever, and
    -- every reader would have to know about both.
    function normalise_payload(p_payload in clob) return clob;

    function payload_hash(p_payload in clob) return varchar2;

    -- Registers a request, or recognises one already seen. o_result is one of
    -- NEW, DUPLICATE (same payload - o_response_payload carries the stored
    -- outcome to replay) or CONFLICT (same id, different payload).
    procedure register_request(
        p_action_request_id in varchar2,
        p_operation_name    in varchar2,
        p_payload_hash      in varchar2,
        p_payload           in clob,
        o_result            out varchar2,
        o_status            out varchar2,
        o_response_payload  out clob
    );

    -- Sets IE_MFCS_PRD_REQUEST.REQUEST_STATUS and, when given, the stored response payload
    -- that a later duplicate submission will replay.
    procedure set_request_status(
        p_action_request_id in varchar2,
        p_status            in varchar2,
        p_response_payload  in clob default null
    );

    -- Upserts one IE_MFCS_MAP_ENTITY row keyed on the source references. Null
    -- parameters leave the existing column values in place, so partial
    -- knowledge accumulates across steps rather than overwriting.
    procedure save_generated_identifier(
        p_action_request_id   in varchar2,
        p_source_system       in varchar2,
        p_source_style_ref    in varchar2,
        p_mfcs_style_no       in varchar2,
        p_source_variant_ref  in varchar2 default null,
        p_mfcs_sku_no         in varchar2 default null,
        p_sku_size            in varchar2 default null,
        p_sku_width           in varchar2 default null,
        p_source_order_ref    in varchar2 default null,
        p_mfcs_order_no       in varchar2 default null
    );

    -- Builds the canonical status document for a request: status, completed and
    -- failed steps, generated identifiers, errors. Every response the API
    -- returns for an executed request comes from here.
    function build_status_response(
        p_action_request_id in varchar2,
        p_status_override   in varchar2 default null
    ) return clob;
end ie_mfcs_request;
/

create or replace package body ie_mfcs_request as
    function canonicalize(p_element in json_element_t) return clob is
        l_object json_object_t;
        l_array json_array_t;
        l_keys json_key_list;
        l_key varchar2(4000);
        l_tmp varchar2(4000);
        l_result clob;
        l_first boolean := true;
    begin
        if p_element is null then
            return 'null';
        elsif p_element.is_object then
            l_object := treat(p_element as json_object_t);
            l_keys := l_object.get_keys;

            if l_keys is not null then
                for i in 1 .. l_keys.count loop
                    if i < l_keys.count then
                        for j in i + 1 .. l_keys.count loop
                            if l_keys(j) < l_keys(i) then
                                l_tmp := l_keys(i);
                                l_keys(i) := l_keys(j);
                                l_keys(j) := l_tmp;
                            end if;
                        end loop;
                    end if;
                end loop;
            end if;

            l_result := '{';
            if l_keys is not null then
                for i in 1 .. l_keys.count loop
                    l_key := l_keys(i);
                    if upper(l_key) not in ('DATE_TIME_STAMP', 'REQUEST_RECEIVED_AT', 'TRANSPORT_ID') then
                        if l_first then
                            l_first := false;
                        else
                            l_result := l_result || ',';
                        end if;

                        l_result := l_result
                            || '"' || ie_mfcs_event.escape_json(l_key) || '":'
                            || canonicalize(l_object.get(l_key));
                    end if;
                end loop;
            end if;
            l_result := l_result || '}';
            return l_result;
        elsif p_element.is_array then
            l_array := treat(p_element as json_array_t);
            l_result := '[';

            if l_array.get_size > 0 then
                for i in 0 .. l_array.get_size - 1 loop
                    if i > 0 then
                        l_result := l_result || ',';
                    end if;
                    l_result := l_result || canonicalize(l_array.get(i));
                end loop;
            end if;

            l_result := l_result || ']';
            return l_result;
        else
            return p_element.to_string;
        end if;
    end;

    function normalise_payload(p_payload in clob) return clob is
        l_doc json_object_t;
        l_curve json_array_t;

        -- DEPARTMENT, CLASS and SUBCLASS have always been accepted as either a
        -- string or a number, because json_value coerces on the way out. Settling
        -- them as numbers here means the stored document says what it means, and a
        -- reader that does not coerce cannot be surprised.
        procedure numeric_key(p_key in varchar2) is
            l_raw varchar2(120);
        begin
            if not l_doc.has(p_key) then
                return;
            end if;
            l_raw := trim(l_doc.get_string(p_key));
            if l_raw is null then
                return;
            end if;
            l_doc.put(p_key, to_number(l_raw));
        exception
            -- A non-numeric department is a validation error, not a normalisation
            -- one. Leaving it untouched lets validation report it properly instead
            -- of this function failing the request with a conversion error.
            when others then
                null;
        end;

        -- ITEM_NUMBER_TYPE is an MFCS code and reaches MFCS as one, so it is
        -- settled here for the same reason the numeric keys are: the stored
        -- document is what resume replays and what validation reports against.
        -- A caller sending "manl" should not be refused for a difference in case
        -- that carries no meaning, and should not be refused in one operation and
        -- accepted in another because two readers upper-cased differently.
        procedure upper_key(p_key in varchar2) is
            l_raw varchar2(120);
        begin
            if not l_doc.has(p_key) then
                return;
            end if;
            l_raw := upper(trim(l_doc.get_string(p_key)));
            if l_raw is null then
                return;
            end if;
            l_doc.put(p_key, l_raw);
        exception
            when others then
                null;
        end;
    begin
        l_doc := json_object_t.parse(p_payload);

        if l_doc.has('PLMSizeCurveDtl') then
            -- Only when the caller did not also send the canonical key. If both are
            -- present the canonical one wins and the legacy one is dropped, rather
            -- than silently merging two size curves.
            if not l_doc.has('SIZE_CURVE_DETAIL') then
                l_curve := l_doc.get_array('PLMSizeCurveDtl');
                l_doc.put('SIZE_CURVE_DETAIL', l_curve);
            end if;
            l_doc.remove('PLMSizeCurveDtl');
        end if;

        numeric_key('DEPARTMENT');
        numeric_key('CLASS');
        numeric_key('SUBCLASS');
        upper_key('ITEM_NUMBER_TYPE');

        return l_doc.to_clob;
    exception
        -- Malformed JSON is the caller's problem and ie_mfcs_api already reports it
        -- properly. Returning the payload untouched keeps that the single place
        -- that decides what an unparseable document means.
        when others then
            return p_payload;
    end;

    function payload_hash(p_payload in clob) return varchar2 is
        l_element json_element_t;
        l_canonical clob;
        l_hash varchar2(64);
    begin
        l_element := json_element_t.parse(p_payload);
        l_canonical := canonicalize(l_element);

        l_hash := rawtohex(dbms_crypto.hash(l_canonical, dbms_crypto.hash_sh256));

        return lower(l_hash);
    end;

    procedure register_request(
        p_action_request_id in varchar2,
        p_operation_name    in varchar2,
        p_payload_hash      in varchar2,
        p_payload           in clob,
        o_result            out varchar2,
        o_status            out varchar2,
        o_response_payload  out clob
    ) is
        l_existing_hash varchar2(64);
        l_status varchar2(30);
        l_source_system varchar2(60);
        l_source_style_ref varchar2(120);
        l_source_order_ref varchar2(120);
        l_source_version varchar2(60);
        l_style_no varchar2(30);
        l_order_no varchar2(30);
    begin
        select json_value(p_payload, '$.SOURCE_SYSTEM' returning varchar2(60) null on error),
               json_value(p_payload, '$.SOURCE_STYLE_REF' returning varchar2(120) null on error),
               json_value(p_payload, '$.SOURCE_ORDER_REF' returning varchar2(120) null on error),
               json_value(p_payload, '$.SOURCE_VERSION' returning varchar2(60) null on error),
               json_value(p_payload, '$.STYLE' returning varchar2(30) null on error),
               json_value(p_payload, '$.ORDER_NO' returning varchar2(30) null on error)
          into l_source_system, l_source_style_ref, l_source_order_ref, l_source_version,
               l_style_no, l_order_no
          from dual;

        if l_style_no is null and l_source_system is not null and l_source_style_ref is not null then
            select max(mfcs_style_no)
              into l_style_no
              from ie_mfcs_map_entity
             where source_system = l_source_system
               and source_style_ref = l_source_style_ref
               and mfcs_style_no is not null;
        end if;

        if p_operation_name in ('CREATE_STYLE', 'MODIFY_STYLE') then
            l_order_no := null;
        end if;

        begin
            insert into ie_mfcs_prd_request (
                action_request_id,
                operation_name,
                source_system,
                source_style_ref,
                source_order_ref,
                source_version,
                payload_hash,
                request_status,
                style_no,
                order_no,
                request_payload
            ) values (
                p_action_request_id,
                p_operation_name,
                l_source_system,
                l_source_style_ref,
                l_source_order_ref,
                l_source_version,
                p_payload_hash,
                'RECEIVED',
                l_style_no,
                l_order_no,
                p_payload
            );

            commit;
            o_result := 'NEW';
            o_status := 'RECEIVED';
            o_response_payload := null;
            return;
        exception
            when dup_val_on_index then
                null;
        end;

        begin
            select payload_hash, request_status, response_payload
              into l_existing_hash, l_status, o_response_payload
              from ie_mfcs_prd_request
             where action_request_id = p_action_request_id
             for update nowait;
        exception
            when others then
                if sqlcode = -54 then
                    o_result := 'EXECUTING';
                    o_status := 'IN_PROGRESS';
                    o_response_payload := null;
                    rollback;
                    return;
                end if;
                raise;
        end;

        if l_existing_hash <> p_payload_hash then
            o_result := 'CONFLICT';
            o_status := l_status;
        elsif l_status = 'IN_PROGRESS' then
            o_result := 'EXECUTING';
            o_status := l_status;
        elsif l_status = 'FAILED_NO_SIDE_EFFECT' then
            -- Always resumable, and the status name is the reason: nothing was
            -- created, so re-running cannot duplicate anything.
            --
            -- This used to resume only when the stored response mentioned
            -- MFCS_BATCH_WINDOW_ACTIVE, which was written for the one transient
            -- cause that had been seen and never generalised. Every other
            -- transient - a stale token being the common one - replayed its own
            -- failure for ever, so a request that failed on a 401 could never be
            -- retried even once the token was good again.
            update ie_mfcs_prd_request
               set request_status = 'IN_PROGRESS',
                   started_at = coalesce(started_at, systimestamp),
                   last_updated_at = systimestamp
             where action_request_id = p_action_request_id;
            o_result := 'RESUME';
            o_status := 'IN_PROGRESS';
        elsif l_status in ('COMPLETED', 'MANUAL_REVIEW') then
            o_result := 'EXISTING';
            o_status := l_status;
        else
            update ie_mfcs_prd_request
               set request_status = 'IN_PROGRESS',
                   started_at = coalesce(started_at, systimestamp),
                   last_updated_at = systimestamp
             where action_request_id = p_action_request_id;
            o_result := 'RESUME';
            o_status := 'IN_PROGRESS';
        end if;

        commit;
    end;

    procedure set_request_status(
        p_action_request_id in varchar2,
        p_status            in varchar2,
        p_response_payload  in clob default null
    ) is
    begin
        update ie_mfcs_prd_request
           set request_status = p_status,
               response_payload = case when p_response_payload is not null then p_response_payload else response_payload end,
               started_at = case when p_status = 'IN_PROGRESS' then coalesce(started_at, systimestamp) else started_at end,
               completed_at = case when p_status in ('COMPLETED', 'FAILED_NO_SIDE_EFFECT', 'MANUAL_REVIEW') then systimestamp else completed_at end,
               last_updated_at = systimestamp
         where action_request_id = p_action_request_id;

        commit;
    end;

    procedure save_generated_identifier(
        p_action_request_id   in varchar2,
        p_source_system       in varchar2,
        p_source_style_ref    in varchar2,
        p_mfcs_style_no       in varchar2,
        p_source_variant_ref  in varchar2 default null,
        p_mfcs_sku_no         in varchar2 default null,
        p_sku_size            in varchar2 default null,
        p_sku_width           in varchar2 default null,
        p_source_order_ref    in varchar2 default null,
        p_mfcs_order_no       in varchar2 default null
    ) is
    begin
        update ie_mfcs_map_entity
           set mfcs_style_no = coalesce(p_mfcs_style_no, mfcs_style_no),
               mfcs_sku_no = coalesce(p_mfcs_sku_no, mfcs_sku_no),
               sku_size = coalesce(p_sku_size, sku_size),
               sku_width = coalesce(p_sku_width, sku_width),
               mfcs_order_no = coalesce(p_mfcs_order_no, mfcs_order_no),
               last_updated_at = systimestamp
         where source_system = p_source_system
           and nvl(source_style_ref, '-') = nvl(p_source_style_ref, '-')
           and nvl(source_variant_ref, '-') = nvl(p_source_variant_ref, '-')
           and nvl(source_order_ref, '-') = nvl(p_source_order_ref, '-');

        if sql%rowcount = 0 then
            insert into ie_mfcs_map_entity (
                source_system,
                source_style_ref,
                mfcs_style_no,
                source_variant_ref,
                mfcs_sku_no,
                sku_size,
                sku_width,
                source_order_ref,
                mfcs_order_no
            ) values (
                p_source_system,
                p_source_style_ref,
                p_mfcs_style_no,
                p_source_variant_ref,
                p_mfcs_sku_no,
                p_sku_size,
                p_sku_width,
                p_source_order_ref,
                p_mfcs_order_no
            );
        end if;

        update ie_mfcs_prd_request
           set style_no = coalesce(p_mfcs_style_no, style_no),
               order_no = coalesce(p_mfcs_order_no, order_no),
               last_updated_at = systimestamp
         where action_request_id = p_action_request_id;

        commit;
    end;

    function build_status_response(
        p_action_request_id in varchar2,
        p_status_override   in varchar2 default null
    ) return clob is
        l_status varchar2(30);
        l_operation varchar2(30);
        l_style varchar2(30);
        l_order varchar2(30);
        l_failed_step varchar2(60);
        l_response clob;
        l_retryable varchar2(5);
        l_first boolean := true;
    begin
        select operation_name, request_status, style_no, order_no
          into l_operation, l_status, l_style, l_order
          from ie_mfcs_prd_request
         where action_request_id = p_action_request_id;

        l_status := nvl(p_status_override, l_status);

        l_retryable := case when l_status in ('PARTIALLY_COMPLETED', 'OUTCOME_UNKNOWN', 'FAILED_NO_SIDE_EFFECT') then 'true' else 'false' end;
        l_response := '{'
            || '"OPERATION_NAME":"' || ie_mfcs_event.escape_json(l_operation) || '",'
            || '"ACTION_REQUEST_ID":"' || ie_mfcs_event.escape_json(p_action_request_id) || '",'
            || '"STATUS":"' || ie_mfcs_event.escape_json(l_status) || '",'
            || '"RETRYABLE":' || l_retryable || ','
            || '"STYLE":' || case when l_style is null then 'null' else '"' || ie_mfcs_event.escape_json(l_style) || '"' end || ','
            || '"ORDER_NO":' || case when l_order is null then 'null' else '"' || ie_mfcs_event.escape_json(l_order) || '"' end || ','
            || '"SIZE_CURVE_DETAIL":[';

        for r in (
            select source_variant_ref, sku_size, sku_width, mfcs_sku_no
              from ie_mfcs_map_entity m
              join ie_mfcs_prd_request r
                on r.source_system = m.source_system
               and nvl(r.source_style_ref, '-') = nvl(m.source_style_ref, '-')
             where r.action_request_id = p_action_request_id
               and m.mfcs_sku_no is not null
             order by source_variant_ref
        ) loop
            if l_first then
                l_first := false;
            else
                l_response := l_response || ',';
            end if;

            l_response := l_response
                || '{"SOURCE_VARIANT_REF":"' || ie_mfcs_event.escape_json(r.source_variant_ref) || '",'
                || '"SKU_SIZE":"' || ie_mfcs_event.escape_json(r.sku_size) || '",'
                || '"SKU_WIDTH":"' || ie_mfcs_event.escape_json(r.sku_width) || '",'
                || '"SKU_ID":"' || ie_mfcs_event.escape_json(r.mfcs_sku_no) || '"}';
        end loop;

        l_response := l_response || '],"COMPLETED_STEPS":[';
        l_first := true;
        for s in (
            select step_code
              from ie_mfcs_prd_request_step
             where action_request_id = p_action_request_id
               and step_status = 'SUCCEEDED'
             order by step_sequence
        ) loop
            if l_first then
                l_first := false;
            else
                l_response := l_response || ',';
            end if;
            l_response := l_response || '"' || ie_mfcs_event.escape_json(s.step_code) || '"';
        end loop;

        l_response := l_response || '],"FAILED_STEP":';
        begin
            select step_code
              into l_failed_step
              from (
                  select step_code
                    from ie_mfcs_prd_request_step
                   where action_request_id = p_action_request_id
                     and step_status in ('FAILED', 'OUTCOME_UNKNOWN')
                   order by step_sequence
              )
             where rownum = 1;
            l_response := l_response || '"' || ie_mfcs_event.escape_json(l_failed_step) || '"';
        exception
            when no_data_found then
                l_response := l_response || 'null';
        end;

        l_response := l_response || ',"GENERATED_IDENTIFIERS":{'
            || '"STYLE":' || case when l_style is null then 'null' else '"' || ie_mfcs_event.escape_json(l_style) || '"' end
            || ',"ORDER_NO":' || case when l_order is null then 'null' else '"' || ie_mfcs_event.escape_json(l_order) || '"' end
            || '},"ERRORS":[]}';

        return l_response;
    end;
end ie_mfcs_request;
/

-- ==== 20_packages/04_ie_mfcs_step.sql

-- Step graph and attempt journalling for a registered request.
--
-- initialize_steps writes the full plan for an operation into IE_MFCS_PRD_REQUEST_STEP before
-- anything runs; the orchestrator then walks it by asking first_runnable_step.
-- Every outbound HTTP call is bracketed by begin_attempt / complete_attempt,
-- which is what makes a request resumable: the journal knows what was sent,
-- what came back, and which step to pick up from.

create or replace package ie_mfcs_step authid definer as
    -- Writes the operation's full step plan into IE_MFCS_PRD_REQUEST_STEP, all PENDING. See the
    -- body for why every operation gets its whole write set.
    procedure initialize_steps(
        p_action_request_id in varchar2,
        p_operation_name    in varchar2
    );

    -- The lowest-sequence step still PENDING, FAILED or OUTCOME_UNKNOWN, or
    -- null when the request is complete. FAILED is runnable on purpose: that
    -- is what resume means.
    function first_runnable_step(
        p_action_request_id in varchar2
    ) return varchar2;

    -- Whether a step has already succeeded, used by resume to skip work that
    -- is done.
    function step_succeeded(
        p_action_request_id in varchar2,
        p_step_code         in varchar2
    ) return boolean;

    -- Records a step's current status and, on failure, the error that stopped it.
    procedure set_step_status(
        p_action_request_id in varchar2,
        p_step_code         in varchar2,
        p_status            in varchar2,
        p_entity_identifier in varchar2 default null,
        p_error_code        in varchar2 default null,
        p_error_message     in varchar2 default null
    );

    -- Journals an outbound call before it is sent, returning the attempt id and
    -- a fresh correlation id. Recording first is deliberate: if the process
    -- dies mid-call, the journal still shows a call may have gone out.
    procedure begin_attempt(
        p_action_request_id in varchar2,
        p_step_code         in varchar2,
        p_http_method       in varchar2,
        p_endpoint          in varchar2,
        p_request_payload   in clob,
        o_attempt_id        out number,
        o_correlation_id    out varchar2
    );

    -- Closes an attempt with what came back - or with OUTCOME_UNKNOWN when the
    -- transport failed after the request may have been sent.
    procedure complete_attempt(
        p_attempt_id       in number,
        p_attempt_status   in varchar2,
        p_http_status      in number default null,
        p_response_payload in clob default null
    );
end ie_mfcs_step;
/

create or replace package body ie_mfcs_step as
    procedure add_step(
        p_action_request_id in varchar2,
        p_step_code in varchar2,
        p_step_sequence in number
    ) is
    begin
        merge into ie_mfcs_prd_request_step s
        using (
            select p_action_request_id action_request_id,
                   p_step_code step_code,
                   p_step_sequence step_sequence
              from dual
        ) x
        on (s.action_request_id = x.action_request_id and s.step_code = x.step_code)
        when not matched then insert (
            action_request_id,
            step_code,
            step_sequence,
            step_status
        ) values (
            x.action_request_id,
            x.step_code,
            x.step_sequence,
            'PENDING'
        );
    end;

    procedure initialize_steps(
        p_action_request_id in varchar2,
        p_operation_name    in varchar2
    ) is
    begin
        add_step(p_action_request_id, 'VALIDATE_REQUEST', 10);

        if p_operation_name in ('CREATE_STYLE', 'CREATE_ALL') then
            add_step(p_action_request_id, 'RESERVE_ITEM_NUMBERS', 20);
            add_step(p_action_request_id, 'CREATE_PARENT_ITEM_HIERARCHY', 30);
            add_step(p_action_request_id, 'CREATE_PARENT_ITEM_SOURCING', 35);
            add_step(p_action_request_id, 'CREATE_CHILD_ITEM_HIERARCHY', 40);

            add_step(p_action_request_id, 'CREATE_ITEM_SOURCING', 50);
            add_step(p_action_request_id, 'CREATE_ITEM_COUNTRIES_OF_MANUFACTURE', 55);
            add_step(p_action_request_id, 'CREATE_ITEM_UDAS', 60);
            -- Season, image and tariff attributes. Each is a no-op when the
            -- document carries none: the mapper returns collectionSize 0 and the
            -- orchestrator skips the call rather than sending an empty array.
            add_step(p_action_request_id, 'CREATE_ITEM_SEASONS', 62);
            add_step(p_action_request_id, 'CREATE_ITEM_IMAGES', 64);
            add_step(p_action_request_id, 'CREATE_ITEM_HTS', 66);
            if ie_mfcs_config.get_config('FEATURE_ITEM_LOCATIONS_YN', 'N') = 'Y' then
                add_step(p_action_request_id, 'CREATE_ITEM_LOCATIONS', 70);
            end if;
            add_step(p_action_request_id, 'APPROVE_ITEMS', 80);
            -- Barcodes come last, after approval, and the ordering is not
            -- cosmetic. A level-3 item is refused while its parent SKU is still
            -- in worksheet status: "This item's parent must be in submitted
            -- status before the item can be submitted" - proven live, 2026-09-01.
            -- No-op when the document carries no SKU_UPCS, which is how a style
            -- without barcodes stays legal.
            add_step(p_action_request_id, 'CREATE_REFERENCE_ITEMS', 85);
        elsif p_operation_name in ('MODIFY_STYLE', 'CREATE_ORDER', 'MODIFY_ORDER') then
            -- The whole style write set, every time, for every operation that touches
            -- an existing style. Not a diff.
            --
            -- This layer does not know what changed. It receives a document describing
            -- what the style should now be, and the only safe reading of that is that
            -- all of it may have changed. Sending a subset because nothing here looks
            -- different would mean the one field that did change is the one left
            -- behind, and MFCS answers a write that changes nothing with SUCCESS, so
            -- nothing would ever reveal the omission.
            --
            -- An order carries the same set. A purchase order is placed against a
            -- style's SKUs at a cost, in a country, from a supplier - ordering is a
            -- statement about the style, not only about the order, so the style is
            -- brought up to date first and the order is placed against what results.
            --
            -- ENSURE_STYLE_SKUS runs first because everything after it addresses SKUs
            -- by number. It is the one genuinely conditional step, and it conditions
            -- on the tenant rather than on this database: MFCS will not repurpose an
            -- existing SKU, since a diff combination defines the item, so a colour or
            -- size the style lacks has to become a new child before anything can
            -- reference it.
            add_step(p_action_request_id, 'ENSURE_STYLE_SKUS', 25);
            add_step(p_action_request_id, 'CREATE_ITEM_HIERARCHY', 30);
            add_step(p_action_request_id, 'CREATE_ITEM_SOURCING', 40);
            add_step(p_action_request_id, 'CREATE_ITEM_COUNTRIES_OF_MANUFACTURE', 45);
            add_step(p_action_request_id, 'CREATE_ITEM_UDAS', 50);
            add_step(p_action_request_id, 'CREATE_ITEM_SEASONS', 52);
            add_step(p_action_request_id, 'CREATE_ITEM_IMAGES', 54);
            add_step(p_action_request_id, 'CREATE_ITEM_HTS', 56);
            if ie_mfcs_config.get_config('FEATURE_ITEM_LOCATIONS_YN', 'N') = 'Y' then
                add_step(p_action_request_id, 'CREATE_ITEM_LOCATIONS', 60);
            end if;
            add_step(p_action_request_id, 'APPROVE_ITEMS', 70);
            -- After approval, for the same reason as the create branch.
            add_step(p_action_request_id, 'CREATE_REFERENCE_ITEMS', 75);
        end if;

        if p_operation_name = 'CREATE_ALL'
           and ie_mfcs_config.get_config('FEATURE_INITIAL_RETAIL_YN', 'N') = 'Y' then
            add_step(p_action_request_id, 'APPLY_INITIAL_RETAIL', 80);
        end if;

        -- No verification step follows the order write. purchaseOrders/create
        -- answers a create it did not make with an error, not with SUCCESS, so
        -- its 200 is evidence on its own - unlike items/update, which is why the
        -- item steps still read back. A GET against the procurement feed here
        -- bought nothing but latency: the feed lags the write, so the step slept
        -- through up to twelve ten-second retries waiting to be told what the
        -- create response had already said.
        --
        -- The order number is not lost by removing it. persist_po_number writes
        -- it the moment RESERVE_ORDER_NUMBER succeeds, so it reaches IE_MFCS_PRD_REQUEST and
        -- the status document even when the create that follows fails.
        if p_operation_name in ('CREATE_ORDER', 'CREATE_ALL') then
            add_step(p_action_request_id, 'RESERVE_ORDER_NUMBER', 90);
            add_step(p_action_request_id, 'CREATE_PURCHASE_ORDER', 100);
        elsif p_operation_name = 'MODIFY_ORDER' then
            add_step(p_action_request_id, 'CREATE_PURCHASE_ORDER', 100);
            -- The header update above ignores its details array on this tenant
            -- (SUCCESS, nothing changes - proven live). The lines are synced
            -- through the purchaseOrder/details services in their own step,
            -- which reads the order first because what it sends depends on what
            -- the order currently holds. That step does its own read-back, and
            -- keeps it: here a SUCCESS genuinely is not evidence.
            add_step(p_action_request_id, 'SYNC_ORDER_LINES', 105);
        end if;

        commit;
    end;

    function first_runnable_step(
        p_action_request_id in varchar2
    ) return varchar2 is
        l_step_code varchar2(60);
    begin
        select step_code
          into l_step_code
          from (
              select step_code
                from ie_mfcs_prd_request_step
               where action_request_id = p_action_request_id
                 and step_status in ('PENDING', 'FAILED', 'OUTCOME_UNKNOWN')
               order by step_sequence
          )
         where rownum = 1;

        return l_step_code;
    exception
        when no_data_found then
            return null;
    end;

    function step_succeeded(
        p_action_request_id in varchar2,
        p_step_code         in varchar2
    ) return boolean is
        l_count number;
    begin
        select count(*)
          into l_count
          from ie_mfcs_prd_request_step
         where action_request_id = p_action_request_id
           and step_code = p_step_code
           and step_status = 'SUCCEEDED';

        return l_count > 0;
    end;

    procedure set_step_status(
        p_action_request_id in varchar2,
        p_step_code         in varchar2,
        p_status            in varchar2,
        p_entity_identifier in varchar2 default null,
        p_error_code        in varchar2 default null,
        p_error_message     in varchar2 default null
    ) is
    begin
        update ie_mfcs_prd_request_step
           set step_status = p_status,
               entity_identifier = coalesce(p_entity_identifier, entity_identifier),
               started_at = case when p_status = 'IN_PROGRESS' then coalesce(started_at, systimestamp) else started_at end,
               completed_at = case when p_status in ('SUCCEEDED', 'FAILED', 'OUTCOME_UNKNOWN', 'SKIPPED') then systimestamp else completed_at end,
               last_error_code = p_error_code,
               last_error_message = substr(p_error_message, 1, 4000)
         where action_request_id = p_action_request_id
           and step_code = p_step_code;

        commit;
    end;

    procedure begin_attempt(
        p_action_request_id in varchar2,
        p_step_code         in varchar2,
        p_http_method       in varchar2,
        p_endpoint          in varchar2,
        p_request_payload   in clob,
        o_attempt_id        out number,
        o_correlation_id    out varchar2
    ) is
        pragma autonomous_transaction;
        l_attempt_number number;
        l_guid varchar2(32);
    begin
        select nvl(max(attempt_number), 0) + 1
          into l_attempt_number
          from ie_mfcs_prd_step_attempt
         where action_request_id = p_action_request_id
           and step_code = p_step_code;

        l_guid := lower(rawtohex(sys_guid()));
        o_correlation_id := substr(l_guid, 1, 8) || '-'
                         || substr(l_guid, 9, 4) || '-'
                         || substr(l_guid, 13, 4) || '-'
                         || substr(l_guid, 17, 4) || '-'
                         || substr(l_guid, 21);

        o_attempt_id := ie_mfcs_seq_attempt_id.nextval;

        insert into ie_mfcs_prd_step_attempt (
            attempt_id,
            action_request_id,
            step_code,
            attempt_number,
            correlation_id,
            http_method,
            endpoint,
            request_payload,
            attempt_status
        ) values (
            o_attempt_id,
            p_action_request_id,
            p_step_code,
            l_attempt_number,
            o_correlation_id,
            p_http_method,
            p_endpoint,
            p_request_payload,
            'IN_PROGRESS'
        );

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'ATTEMPT_BEGIN',
            p_step_code => p_step_code,
            p_attempt_id => o_attempt_id,
            p_message => 'MFCS attempt opened.',
            p_detail_payload => '{"attemptNumber":' || l_attempt_number
                || ',"correlationId":"' || ie_mfcs_event.escape_json(o_correlation_id)
                || '","httpMethod":"' || ie_mfcs_event.escape_json(p_http_method)
                || '","endpoint":"' || ie_mfcs_event.escape_json(p_endpoint) || '"}'
        );

        commit;
    end;

    procedure complete_attempt(
        p_attempt_id       in number,
        p_attempt_status   in varchar2,
        p_http_status      in number default null,
        p_response_payload in clob default null
    ) is
        pragma autonomous_transaction;
        l_action_request_id varchar2(80);
        l_step_code varchar2(60);
    begin
        update ie_mfcs_prd_step_attempt
           set attempt_status = p_attempt_status,
               http_status = p_http_status,
               response_payload = p_response_payload,
               completed_at = systimestamp
         where attempt_id = p_attempt_id
         returning action_request_id, step_code
              into l_action_request_id, l_step_code;

        ie_mfcs_event.log_event(
            p_action_request_id => l_action_request_id,
            p_event_phase => 'ATTEMPT_COMPLETE',
            p_step_code => l_step_code,
            p_attempt_id => p_attempt_id,
            p_event_level => case when p_attempt_status = 'SUCCEEDED' then 'INFO' else 'ERROR' end,
            p_message => 'MFCS attempt completed.',
            p_detail_payload => '{"attemptStatus":"' || ie_mfcs_event.escape_json(p_attempt_status)
                || '","httpStatus":' || coalesce(to_char(p_http_status), 'null')
                || ',"responseBytes":' || coalesce(to_char(dbms_lob.getlength(p_response_payload)), '0') || '}'
        );

        commit;
    end;
end ie_mfcs_step;
/

-- ==== 20_packages/05_ie_mfcs_validation.sql

-- Field-level validation of the inbound Office document.
--
-- Runs before anything is registered or sent, so a rejected request has no
-- side effects anywhere. Checks presence, types, dates and reference values
-- translations; rules MFCS only enforces late (OTB_EOW_DATE falling on a
-- Sunday, for one) are checked here so they fail before a style exists and an
-- order number is burned.

create or replace package ie_mfcs_validation authid definer as
    -- Returns true when the document is executable. On false, o_errors is a
    -- JSON array of {FIELD, CODE, MESSAGE} - every problem found, not only
    -- the first.
    function validate_request(
        p_payload in clob,
        o_errors  out clob
    ) return boolean;
end ie_mfcs_validation;
/

create or replace package body ie_mfcs_validation as
    -- Whether a barcode is a well-formed EAN-13.
    --
    -- Worth checking here because MFCS will not: it validates the length of the
    -- number but not its check digit, so a transposed pair of digits is accepted
    -- and creates a barcode that no scanner will ever match. Catching it costs
    -- nothing; finding it later means the item exists and cannot be unmade.
    function is_valid_ean13(p_upc in varchar2) return boolean is
        l_sum pls_integer := 0;
        l_digit pls_integer;
    begin
        if p_upc is null or length(p_upc) <> 13 or not regexp_like(p_upc, '^[0-9]{13}$') then
            return false;
        end if;
        for i in 1 .. 12 loop
            l_digit := to_number(substr(p_upc, i, 1));
            l_sum := l_sum + l_digit * case when mod(i, 2) = 0 then 3 else 1 end;
        end loop;
        return to_number(substr(p_upc, 13, 1)) = mod(10 - mod(l_sum, 10), 10);
    end;

    procedure add_error(
        p_errors in out nocopy json_array_t,
        p_field  in varchar2,
        p_code   in varchar2,
        p_msg    in varchar2
    ) is
        l_error json_object_t := json_object_t();
    begin
        l_error.put('FIELD', p_field);
        l_error.put('CODE', p_code);
        l_error.put('MESSAGE', p_msg);
        p_errors.append(l_error);
    end;

    function has_config(p_key in varchar2) return boolean is
    begin
        return ie_mfcs_config.get_config(p_key) is not null;
    end;

    -- ITEM_NUMBER / ITEM_NUMBER_TYPE: the caller choosing its own MFCS item
    -- numbers instead of taking reserved ones.
    --
    -- The rules exist because every one of them is a caller mistake that MFCS
    -- would either accept silently or refuse far downstream, after other records
    -- had been made. A style whose number is 26 characters fails at items/create
    -- with the style already half built; two SKUs sharing a number produce one
    -- SKU and a confusing success.
    --
    -- MANL is the only type a caller can supply. ITEM demands exactly nine
    -- characters with a valid Oracle check digit, so a chosen ITEM number is
    -- refused as "Invalid Check Digit" - verified live on STG, 2026-09-10.
    procedure validate_item_numbers(
        p_payload   in clob,
        p_operation in varchar2,
        p_errors    in out nocopy json_array_t
    ) is
        c_max_length constant pls_integer := 25;
        l_item_number varchar2(4000);
        l_type varchar2(4000);
        l_rows number;
        l_numbered number;
        l_distinct number;
        l_too_long number;
    begin
        select trim(json_value(p_payload, '$.ITEM_NUMBER' returning varchar2(4000) null on error)),
               upper(trim(json_value(p_payload, '$.ITEM_NUMBER_TYPE' returning varchar2(4000) null on error)))
          into l_item_number, l_type
          from dual;

        -- The pair travels together or not at all. A type without a number is the
        -- case worth naming: the caller believes it is choosing the number, and
        -- something upstream dropped it. Accepting that would reserve a number
        -- and create a style nobody asked for under a number nobody expects.
        if l_type is not null and l_item_number is null then
            add_error(p_errors, 'ITEM_NUMBER', 'REQUIRED_WITH_TYPE',
                'ITEM_NUMBER is required when ITEM_NUMBER_TYPE is supplied.');
        end if;

        if l_item_number is not null and l_type is null then
            add_error(p_errors, 'ITEM_NUMBER_TYPE', 'REQUIRED_WITH_ITEM_NUMBER',
                'ITEM_NUMBER_TYPE is required when ITEM_NUMBER is supplied.');
        end if;

        if l_type is not null and l_type <> 'MANL' then
            add_error(p_errors, 'ITEM_NUMBER_TYPE', 'UNSUPPORTED_ITEM_NUMBER_TYPE',
                'ITEM_NUMBER_TYPE must be MANL. MFCS refuses a caller-chosen number of any other type.');
        end if;

        select count(*),
               count(item_number),
               count(distinct item_number),
               count(case when lengthb(item_number) > c_max_length then 1 end)
          into l_rows, l_numbered, l_distinct, l_too_long
          from json_table(p_payload, '$.SIZE_CURVE_DETAIL[*]'
              columns item_number varchar2(4000) path '$.ITEM_NUMBER' null on error
          );

        if l_item_number is not null and lengthb(l_item_number) > c_max_length then
            add_error(p_errors, 'ITEM_NUMBER', 'ITEM_NUMBER_TOO_LONG',
                'ITEM_NUMBER must be ' || c_max_length || ' characters or fewer.');
        end if;

        if l_too_long > 0 then
            add_error(p_errors, 'SIZE_CURVE_DETAIL.ITEM_NUMBER', 'ITEM_NUMBER_TOO_LONG',
                'Every SIZE_CURVE_DETAIL.ITEM_NUMBER must be ' || c_max_length || ' characters or fewer.');
        end if;

        -- All or nothing across the request. A style numbered by the caller whose
        -- SKUs are numbered by MFCS is legal at the tenant and almost certainly
        -- not what anyone meant, and it leaves a style nobody can reason about
        -- later: half its identifiers mean something to the caller, half do not.
        if l_item_number is not null and l_rows > 0 and l_numbered < l_rows then
            add_error(p_errors, 'SIZE_CURVE_DETAIL.ITEM_NUMBER', 'ITEM_NUMBER_REQUIRED_FOR_ALL',
                'When ITEM_NUMBER is supplied for the style, every SIZE_CURVE_DETAIL row must supply one too.');
        end if;

        if l_item_number is null and l_numbered > 0 then
            add_error(p_errors, 'ITEM_NUMBER', 'REQUIRED_WITH_SKU_ITEM_NUMBERS',
                'ITEM_NUMBER is required for the style when SIZE_CURVE_DETAIL rows supply one.');
        end if;

        -- Two SKUs sharing a number is one SKU, and MFCS would not say so.
        if l_numbered > 0 and l_distinct < l_numbered then
            add_error(p_errors, 'SIZE_CURVE_DETAIL.ITEM_NUMBER', 'DUPLICATE_ITEM_NUMBER',
                'SIZE_CURVE_DETAIL.ITEM_NUMBER must be unique within the request.');
        end if;

        if l_item_number is not null and l_numbered > 0 then
            select count(*)
              into l_distinct
              from json_table(p_payload, '$.SIZE_CURVE_DETAIL[*]'
                  columns item_number varchar2(4000) path '$.ITEM_NUMBER' null on error
              )
             where item_number = l_item_number;

            if l_distinct > 0 then
                add_error(p_errors, 'SIZE_CURVE_DETAIL.ITEM_NUMBER', 'DUPLICATE_ITEM_NUMBER',
                    'A SKU cannot carry the same ITEM_NUMBER as its style.');
            end if;
        end if;

        -- Only the operations that create the items. On a modify the style and its
        -- SKUs already exist and are addressed by STYLE and SKU_ID; a number
        -- offered here would be an assignment MFCS has no service to honour.
        if l_item_number is not null and p_operation not in ('CREATE_STYLE', 'CREATE_ALL') then
            add_error(p_errors, 'ITEM_NUMBER', 'ITEM_NUMBER_NOT_ALLOWED',
                'ITEM_NUMBER is only accepted for CREATE_STYLE and CREATE_ALL.');
        end if;

        -- ITEM_DESCRIPTION travels the same way as ITEM_NUMBER and is checked the
        -- same way: optional, and refused when it is longer than the field it is
        -- going into. MFCS truncates silently, which would leave two SKUs sharing
        -- a description that differed only past the 250th character.
        select trim(json_value(p_payload, '$.ITEM_DESCRIPTION' returning varchar2(4000) null on error))
          into l_item_number
          from dual;

        if l_item_number is not null and lengthb(l_item_number) > 250 then
            add_error(p_errors, 'ITEM_DESCRIPTION', 'ITEM_DESCRIPTION_TOO_LONG',
                'ITEM_DESCRIPTION must be 250 characters or fewer.');
        end if;

        select count(*)
          into l_too_long
          from json_table(p_payload, '$.SIZE_CURVE_DETAIL[*]'
              columns item_description varchar2(4000) path '$.ITEM_DESCRIPTION' null on error
          )
         where lengthb(item_description) > 250;

        if l_too_long > 0 then
            add_error(p_errors, 'SIZE_CURVE_DETAIL.ITEM_DESCRIPTION', 'ITEM_DESCRIPTION_TOO_LONG',
                'Every SIZE_CURVE_DETAIL.ITEM_DESCRIPTION must be 250 characters or fewer.');
        end if;
    end;

    -- Whether the tenant holds this reference value.
    --
    -- These checks used to read MAP.* config, a list maintained alongside master
    -- data and free to disagree with it - which is how MAP.COLOUR.BLACK came to
    -- exist, offering a colour the tenant would reject after an item number had
    -- already been burned. Master data is what the tenant actually has.
    --
    -- Returns true when the type has not been loaded at all. A database whose
    -- master data has never been refreshed should not reject every document; it
    -- should behave as it did before the check existed. The refresh log is where
    -- an empty type is visible, not here.
    function has_master(
        p_type   in varchar2,
        p_code   in varchar2,
        p_parent in varchar2 default '~'
    ) return boolean is
        l_loaded number;
        l_found number;
    begin
        if p_code is null then
            return false;
        end if;

        select count(*) into l_loaded from ie_mfcs_ref_master_data where data_type = p_type;
        if l_loaded = 0 then
            return true;
        end if;

        select count(*)
          into l_found
          from ie_mfcs_ref_master_data
         where data_type = p_type
           and data_code = p_code
           and parent_code = nvl(p_parent, '~');
        return l_found > 0;
    end;

    function validate_request(
        p_payload in clob,
        o_errors  out clob
    ) return boolean is
        l_errors json_array_t := json_array_t();
        l_action_request_id varchar2(80);
        l_operation varchar2(30);
        l_source_system varchar2(60);
        l_source_style_ref varchar2(120);
        l_source_order_ref varchar2(120);
        l_style varchar2(30);
        l_order_no varchar2(30);
        l_delivery_loc varchar2(30);
        l_department varchar2(30);
        l_class varchar2(30);
        l_subclass varchar2(30);
        l_supplier varchar2(30);
        l_country varchar2(30);
        l_currency varchar2(30);
        l_colour varchar2(60);
        l_unit_cost number;
        l_retail_price number;
        l_not_before date;
        l_not_after date;
        l_earliest date;
        l_latest date;
        l_not_before_text varchar2(30);
        l_not_after_text varchar2(30);
        l_earliest_text varchar2(30);
        l_latest_text varchar2(30);
        l_otb_eow_text varchar2(30);
        l_otb_eow date;
        l_week_end_day varchar2(20);
        l_count number;
        l_distinct_count number;
        l_parsed json_element_t;
    begin
        begin
            l_parsed := json_element_t.parse(p_payload);
        exception
            when others then
                add_error(l_errors, '$', 'INVALID_JSON', sqlerrm);
                o_errors := l_errors.to_clob;
                return false;
        end;

        select json_value(p_payload, '$.ACTION_REQUEST_ID' returning varchar2(80) null on error),
               json_value(p_payload, '$.OPERATION_NAME' returning varchar2(30) null on error),
               json_value(p_payload, '$.SOURCE_SYSTEM' returning varchar2(60) null on error),
               json_value(p_payload, '$.SOURCE_STYLE_REF' returning varchar2(120) null on error),
               json_value(p_payload, '$.SOURCE_ORDER_REF' returning varchar2(120) null on error),
               json_value(p_payload, '$.STYLE' returning varchar2(30) null on error),
               json_value(p_payload, '$.ORDER_NO' returning varchar2(30) null on error),
               json_value(p_payload, '$.DELIVERY_LOC' returning varchar2(30) null on error),
               json_value(p_payload, '$.DEPARTMENT' returning varchar2(30) null on error),
               json_value(p_payload, '$.CLASS' returning varchar2(30) null on error),
               json_value(p_payload, '$.SUBCLASS' returning varchar2(30) null on error),
               json_value(p_payload, '$.SUPPLIER' returning varchar2(30) null on error),
               json_value(p_payload, '$.ORIGIN_COUNTRY' returning varchar2(30) null on error),
               json_value(p_payload, '$.CURRENCY_CODE' returning varchar2(30) null on error),
               json_value(p_payload, '$.COLOUR' returning varchar2(60) null on error),
               json_value(p_payload, '$.UNIT_COST' returning number null on error),
               json_value(p_payload, '$.RETAIL_PRICE' returning number null on error)
          into l_action_request_id, l_operation, l_source_system, l_source_style_ref,
               l_source_order_ref, l_style, l_order_no, l_delivery_loc, l_department,
               l_class, l_subclass, l_supplier, l_country, l_currency, l_colour,
               l_unit_cost, l_retail_price
          from dual;

        if trim(l_action_request_id) is null then
            add_error(l_errors, 'ACTION_REQUEST_ID', 'REQUIRED', 'ACTION_REQUEST_ID is required.');
        end if;

        if trim(l_operation) is null then
            add_error(l_errors, 'OPERATION_NAME', 'REQUIRED', 'OPERATION_NAME is required.');
        elsif l_operation not in ('CREATE_STYLE', 'MODIFY_STYLE', 'CREATE_ORDER', 'MODIFY_ORDER', 'CREATE_ALL') then
            add_error(l_errors, 'OPERATION_NAME', 'UNSUPPORTED_OPERATION', 'Unsupported OPERATION_NAME.');
        end if;

        if trim(l_source_system) is null then
            add_error(l_errors, 'SOURCE_SYSTEM', 'REQUIRED', 'SOURCE_SYSTEM is required.');
        end if;

        if trim(l_source_style_ref) is null and l_operation in ('CREATE_STYLE', 'MODIFY_STYLE', 'CREATE_ALL') then
            add_error(l_errors, 'SOURCE_STYLE_REF', 'REQUIRED', 'SOURCE_STYLE_REF is required.');
        end if;

        if trim(l_source_order_ref) is null and l_operation in ('CREATE_ORDER', 'MODIFY_ORDER', 'CREATE_ALL') then
            add_error(l_errors, 'SOURCE_ORDER_REF', 'REQUIRED', 'SOURCE_ORDER_REF is required.');
        end if;

        if l_operation in ('CREATE_STYLE', 'CREATE_ORDER', 'CREATE_ALL') then
            if trim(l_department) is null then
                add_error(l_errors, 'DEPARTMENT', 'REQUIRED', 'DEPARTMENT is required for create operations.');
            end if;
            if trim(l_class) is null then
                add_error(l_errors, 'CLASS', 'REQUIRED', 'CLASS is required for create operations.');
            end if;
            if trim(l_subclass) is null then
                add_error(l_errors, 'SUBCLASS', 'REQUIRED', 'SUBCLASS is required for create operations.');
            end if;
            if trim(l_supplier) is null then
                add_error(l_errors, 'SUPPLIER', 'REQUIRED', 'SUPPLIER is required for create operations.');
            end if;
            if trim(l_country) is null then
                add_error(l_errors, 'ORIGIN_COUNTRY', 'REQUIRED', 'ORIGIN_COUNTRY is required for create operations.');
            end if;
            if trim(l_currency) is null then
                add_error(l_errors, 'CURRENCY_CODE', 'REQUIRED', 'CURRENCY_CODE is required for create operations.');
            end if;
            if trim(l_colour) is null then
                add_error(l_errors, 'COLOUR', 'REQUIRED', 'COLOUR is required for create operations.');
            end if;
        end if;

        select count(*)
          into l_count
          from json_table(p_payload, '$.SIZE_CURVE_DETAIL[*]'
              columns sku_id varchar2(60) path '$.SKU_ID' null on error
          )
         where sku_id is not null;

        if l_operation = 'CREATE_ALL' then
            if l_style is not null then
                add_error(l_errors, 'STYLE', 'CREATE_IDENTIFIER_MUST_BE_NULL', 'STYLE must be null for CREATE_ALL.');
            end if;
            if l_count > 0 then
                add_error(l_errors, 'SIZE_CURVE_DETAIL.SKU_ID', 'CREATE_IDENTIFIER_MUST_BE_NULL', 'SKU_ID must be null for CREATE_ALL.');
            end if;
            if l_order_no is not null then
                add_error(l_errors, 'ORDER_NO', 'CREATE_IDENTIFIER_MUST_BE_NULL', 'ORDER_NO must be null for CREATE_ALL.');
            end if;
        elsif l_operation = 'CREATE_STYLE' then
            if l_style is not null then
                add_error(l_errors, 'STYLE', 'CREATE_IDENTIFIER_MUST_BE_NULL', 'STYLE must be null for CREATE_STYLE.');
            end if;
            if l_count > 0 then
                add_error(l_errors, 'SIZE_CURVE_DETAIL.SKU_ID', 'CREATE_IDENTIFIER_MUST_BE_NULL', 'SKU_ID must be null for CREATE_STYLE.');
            end if;
        elsif l_operation = 'CREATE_ORDER' then
            if l_order_no is not null then
                add_error(l_errors, 'ORDER_NO', 'CREATE_IDENTIFIER_MUST_BE_NULL', 'ORDER_NO must be null for CREATE_ORDER.');
            end if;
            if trim(l_style) is null then
                select count(*)
                  into l_count
                  from ie_mfcs_map_entity
                 where source_system = l_source_system
                   and source_style_ref = l_source_style_ref
                   and mfcs_style_no is not null;
                if l_count = 0 then
                    add_error(l_errors, 'STYLE', 'STYLE_REQUIRED_OR_RESOLVABLE', 'STYLE is required or must be resolvable for CREATE_ORDER.');
                end if;
            end if;
        elsif l_operation = 'MODIFY_ORDER' then
            if l_order_no is null then
                add_error(l_errors, 'ORDER_NO', 'REQUIRED', 'ORDER_NO is required for MODIFY_ORDER.');
            end if;
            if trim(l_style) is null then
                select count(*)
                  into l_count
                  from ie_mfcs_map_entity
                 where source_system = l_source_system
                   and source_style_ref = l_source_style_ref
                   and mfcs_style_no is not null;
                if l_count = 0 then
                    add_error(l_errors, 'STYLE', 'STYLE_REQUIRED_OR_RESOLVABLE', 'STYLE is required or must be resolvable for MODIFY_ORDER.');
                end if;
            end if;
        elsif l_operation = 'MODIFY_STYLE' then
            if l_style is null then
                add_error(l_errors, 'STYLE', 'REQUIRED', 'STYLE is required for MODIFY_STYLE.');
            end if;
        end if;

        validate_item_numbers(p_payload, l_operation, l_errors);

        select count(*), count(distinct sku_size || '|' || sku_width)
          into l_count, l_distinct_count
          from json_table(p_payload, '$.SIZE_CURVE_DETAIL[*]'
              columns
                  sku_size varchar2(60) path '$.SKU_SIZE' null on error,
                  sku_width varchar2(60) path '$.SKU_WIDTH' null on error
          );

        if l_count = 0 and l_operation in ('CREATE_STYLE', 'CREATE_ORDER', 'CREATE_ALL') then
            add_error(l_errors, 'SIZE_CURVE_DETAIL', 'REQUIRED', 'At least one size/width variant is required.');
        elsif l_count <> l_distinct_count then
            add_error(l_errors, 'SIZE_CURVE_DETAIL', 'DUPLICATE_SIZE_WIDTH', 'Size and width combinations must be unique.');
        end if;

        select count(*)
          into l_count
          from json_table(p_payload, '$.SIZE_CURVE_DETAIL[*]'
              columns sku_qty number path '$.SKU_QTY' null on error
          )
         where sku_qty is null
            or sku_qty <= 0
            or sku_qty <> trunc(sku_qty);

        if l_count > 0 then
            add_error(l_errors, 'SIZE_CURVE_DETAIL.SKU_QTY', 'POSITIVE_WHOLE_NUMBER_REQUIRED', 'Quantities must be positive whole numbers.');
        end if;

        -- Barcodes. Optional by design: a document with no SKU_UPCS produces no
        -- rows here and no errors, which is what lets Office adopt them per style
        -- rather than all at once.
        for u in (
            select source_variant_ref, upc, upc_type, primary_yn
              from json_table(p_payload, '$.SIZE_CURVE_DETAIL[*]'
                  columns
                      source_variant_ref varchar2(120) path '$.SOURCE_VARIANT_REF' null on error,
                      nested path '$.SKU_UPCS[*]'
                          columns (
                              upc        varchar2(30) path '$.UPC' null on error,
                              upc_type   varchar2(10) path '$.UPC_TYPE' null on error,
                              primary_yn varchar2(1)  path '$.PRIMARY_YN' null on error
                          )
              )
             where upc is not null or primary_yn is not null
        ) loop
            if trim(u.upc) is null then
                add_error(l_errors, 'SIZE_CURVE_DETAIL.SKU_UPCS.UPC', 'REQUIRED',
                    'UPC is required on every SKU_UPCS entry.');
            elsif nvl(upper(u.upc_type), 'EAN13') = 'EAN13'
                  and not is_valid_ean13(trim(u.upc)) then
                -- Only EAN13 is checked. MANL barcodes are free-form by definition,
                -- and a real Office SKU carries one of each.
                add_error(l_errors, 'SIZE_CURVE_DETAIL.SKU_UPCS.UPC', 'INVALID_EAN13',
                    'UPC ' || u.upc || ' is not a valid 13-digit EAN with a correct check digit.');
            end if;
        end loop;

        -- Exactly one primary barcode per SKU, for the SKUs that have any.
        --
        -- MFCS does not appear to enforce this and a second primary would be a
        -- silent contradiction in the tenant, which is the failure mode this layer
        -- exists to prevent.
        for v in (
            select source_variant_ref,
                   count(*) upc_count,
                   count(case when upper(primary_yn) = 'Y' then 1 end) primary_count
              from json_table(p_payload, '$.SIZE_CURVE_DETAIL[*]'
                  columns
                      source_variant_ref varchar2(120) path '$.SOURCE_VARIANT_REF' null on error,
                      nested path '$.SKU_UPCS[*]'
                          columns (
                              upc        varchar2(30) path '$.UPC' null on error,
                              primary_yn varchar2(1)  path '$.PRIMARY_YN' null on error
                          )
              )
             where upc is not null
             group by source_variant_ref
        ) loop
            if v.primary_count <> 1 then
                add_error(l_errors, 'SIZE_CURVE_DETAIL.SKU_UPCS.PRIMARY_YN', 'ONE_PRIMARY_UPC_REQUIRED',
                    'SKU ' || v.source_variant_ref || ' has ' || v.primary_count
                    || ' primary barcodes across ' || v.upc_count || '; exactly one must be PRIMARY_YN Y.');
            end if;
        end loop;

        -- UDAs, checked against the tenant's own definitions.
        --
        -- Skipped entirely when master data holds no UDA definitions. On a tenant
        -- whose uda feed has never been refreshed - or has gone empty again, which
        -- is how this one behaved until recently - validating would reject every
        -- document carrying a UDA rather than reject the ones that are wrong.
        select count(*)
          into l_count
          from ie_mfcs_ref_master_data
         where data_type = 'UDA';

        if l_count > 0 then
            for u in (
                select uda_id, uda_value, uda_text, uda_date
                  from json_table(p_payload, '$.STYLE_UDAS[*]'
                      columns
                          uda_id    number        path '$.UDA_ID' null on error,
                          uda_value varchar2(30)  path '$.UDA_VALUE' null on error,
                          uda_text  varchar2(250) path '$.UDA_TEXT' null on error,
                          uda_date  varchar2(30)  path '$.UDA_DATE' null on error
                  )
            ) loop
                if u.uda_id is null then
                    add_error(l_errors, 'STYLE_UDAS.UDA_ID', 'REQUIRED',
                        'UDA_ID is required on every STYLE_UDAS entry.');
                else
                    select count(*)
                      into l_distinct_count
                      from ie_mfcs_ref_master_data
                     where data_type = 'UDA'
                       and data_code = to_char(u.uda_id)
                       and parent_code = '~';

                    if l_distinct_count = 0 then
                        add_error(l_errors, 'STYLE_UDAS.UDA_ID', 'UNKNOWN_UDA',
                            'UDA ' || u.uda_id || ' is not defined on this tenant.');
                    elsif u.uda_value is not null then
                        -- Only list-of-values UDAs have a value set to check
                        -- against; freeform and date carry whatever they carry.
                        select count(*)
                          into l_distinct_count
                          from ie_mfcs_ref_master_data
                         where data_type = 'UDA_VALUE'
                           and parent_code = to_char(u.uda_id)
                           and data_code = u.uda_value;

                        if l_distinct_count = 0 then
                            select count(*)
                              into l_distinct_count
                              from ie_mfcs_ref_master_data
                             where data_type = 'UDA_VALUE'
                               and parent_code = to_char(u.uda_id);

                            -- A UDA with no values loaded is not evidence the value
                            -- is wrong, so only complain when there is a list to
                            -- have failed against.
                            if l_distinct_count > 0 then
                                add_error(l_errors, 'STYLE_UDAS.UDA_VALUE', 'UNKNOWN_UDA_VALUE',
                                    'Value ' || u.uda_value || ' is not in the list of values for UDA '
                                    || u.uda_id || '.');
                            end if;
                        end if;
                    end if;
                end if;
            end loop;
        end if;

        -- Only when the integration has no way to work the SKU out for itself.
        --
        -- ie_mfcs_map_entity is this database's memory, not the tenant's: a style created by
        -- an earlier install, or by somebody else entirely, leaves no row behind and
        -- fails this check while being perfectly orderable. ENSURE_STYLE_SKUS reads
        -- the style and either finds the SKU - recording the mapping as it goes - or
        -- creates it, so with generation on an unresolvable row is not yet an error.
        -- With generation off it still is, and failing here costs no side effect.
        if l_operation in ('CREATE_ORDER', 'MODIFY_STYLE', 'MODIFY_ORDER')
           and ie_mfcs_config.get_config('FEATURE_GENERATE_MISSING_SKUS_YN', 'Y') <> 'Y' then
            for v in (
                select source_variant_ref, sku_id
                  from json_table(p_payload, '$.SIZE_CURVE_DETAIL[*]'
                      columns
                          source_variant_ref varchar2(120) path '$.SOURCE_VARIANT_REF' null on error,
                          sku_id varchar2(60) path '$.SKU_ID' null on error
                  )
            ) loop
                if trim(v.sku_id) is null then
                    select count(*)
                      into l_count
                      from ie_mfcs_map_entity
                     where source_system = l_source_system
                       and source_style_ref = l_source_style_ref
                       and source_variant_ref = v.source_variant_ref
                       and mfcs_sku_no is not null;

                    if l_count = 0 then
                        add_error(l_errors, 'SIZE_CURVE_DETAIL.SKU_ID', 'SKU_REQUIRED_OR_RESOLVABLE', 'SKU_ID is required or must be resolvable for this operation.');
                    end if;
                end if;
            end loop;
        end if;

        if l_delivery_loc is null and l_operation in ('CREATE_ORDER', 'MODIFY_ORDER', 'CREATE_ALL') then
            add_error(l_errors, 'DELIVERY_LOC', 'REQUIRED', 'DELIVERY_LOC is required for order operations.');
        end if;

        if l_operation in ('CREATE_STYLE', 'CREATE_ORDER', 'CREATE_ALL') then
            if l_unit_cost is null or l_unit_cost <= 0 then
                add_error(l_errors, 'UNIT_COST', 'POSITIVE_VALUE_REQUIRED', 'UNIT_COST is required and must be positive.');
            end if;

            if l_retail_price is null or l_retail_price <= 0 then
                add_error(l_errors, 'RETAIL_PRICE', 'POSITIVE_VALUE_REQUIRED', 'RETAIL_PRICE is required and must be positive.');
            end if;
        end if;

        select json_value(p_payload, '$.NOT_BEFORE_DATE' returning varchar2(30) null on error),
               json_value(p_payload, '$.NOT_AFTER_DATE' returning varchar2(30) null on error),
               json_value(p_payload, '$.EARLIEST_SHIP_DATE' returning varchar2(30) null on error),
               json_value(p_payload, '$.LATEST_SHIP_DATE' returning varchar2(30) null on error),
               json_value(p_payload, '$.OTB_EOW_DATE' returning varchar2(30) null on error)
          into l_not_before_text, l_not_after_text, l_earliest_text, l_latest_text, l_otb_eow_text
          from dual;

        select to_date(l_not_before_text default null on conversion error, 'FXYYYY-MM-DD'),
               to_date(l_not_after_text default null on conversion error, 'FXYYYY-MM-DD'),
               to_date(l_earliest_text default null on conversion error, 'FXYYYY-MM-DD'),
               to_date(l_latest_text default null on conversion error, 'FXYYYY-MM-DD')
          into l_not_before, l_not_after, l_earliest, l_latest
          from dual;

        if l_not_before_text is not null and l_not_before is null then
            add_error(l_errors, 'NOT_BEFORE_DATE', 'INVALID_DATE', 'NOT_BEFORE_DATE must use YYYY-MM-DD and be a valid date.');
        end if;
        if l_not_after_text is not null and l_not_after is null then
            add_error(l_errors, 'NOT_AFTER_DATE', 'INVALID_DATE', 'NOT_AFTER_DATE must use YYYY-MM-DD and be a valid date.');
        end if;
        if l_earliest_text is not null and l_earliest is null then
            add_error(l_errors, 'EARLIEST_SHIP_DATE', 'INVALID_DATE', 'EARLIEST_SHIP_DATE must use YYYY-MM-DD and be a valid date.');
        end if;
        if l_latest_text is not null and l_latest is null then
            add_error(l_errors, 'LATEST_SHIP_DATE', 'INVALID_DATE', 'LATEST_SHIP_DATE must use YYYY-MM-DD and be a valid date.');
        end if;

        if l_not_before is not null and l_not_after is not null and l_not_before > l_not_after then
            add_error(l_errors, 'NOT_BEFORE_DATE', 'DATE_RELATIONSHIP', 'NOT_BEFORE_DATE must be on or before NOT_AFTER_DATE.');
        end if;

        if l_earliest is not null and l_latest is not null and l_earliest > l_latest then
            add_error(l_errors, 'EARLIEST_SHIP_DATE', 'DATE_RELATIONSHIP', 'EARLIEST_SHIP_DATE must be on or before LATEST_SHIP_DATE.');
        end if;

        -- OTB end-of-week must land on the retail calendar's week-ending day.
        -- MFCS enforces this at purchase-order create, which is step 100: by then a
        -- style has been created and an order number burned, leaving a partially
        -- completed request over a date the caller could have corrected up front.
        -- The tenant calendar (administration/operations/calendar) starts every
        -- retail month on a Monday, so the week ends Sunday. Configurable because
        -- another tenant may run a different calendar.
        l_otb_eow := to_date(l_otb_eow_text default null on conversion error, 'FXYYYY-MM-DD');
        if l_otb_eow_text is not null and l_otb_eow is null then
            add_error(l_errors, 'OTB_EOW_DATE', 'INVALID_DATE', 'OTB_EOW_DATE must use YYYY-MM-DD and be a valid date.');
        elsif l_otb_eow is not null then
            l_week_end_day := upper(ie_mfcs_config.get_config('MFCS_OTB_EOW_DAY', 'SUNDAY'));
            if l_week_end_day is not null
               and trim(to_char(l_otb_eow, 'DAY', 'NLS_DATE_LANGUAGE=ENGLISH')) <> l_week_end_day then
                add_error(l_errors, 'OTB_EOW_DATE', 'NOT_WEEK_END_DATE',
                    'OTB_EOW_DATE must fall on a ' || initcap(l_week_end_day)
                    || ' to match the retail calendar; '
                    || to_char(l_otb_eow, 'YYYY-MM-DD') || ' is a '
                    || trim(initcap(to_char(l_otb_eow, 'DAY', 'NLS_DATE_LANGUAGE=ENGLISH'))) || '.');
            end if;
        end if;

        -- Non-merchandise costs. Optional, but a malformed one is worth catching
        -- here: MFCS applies expenses during order create, and a rejection there
        -- costs a burned order number.
        for e in (
            select component, component_rate, rn
              from json_table(p_payload, '$.NON_MERCH_COSTS[*]'
                  columns
                      rn for ordinality,
                      component      varchar2(30) path '$.COMPONENT',
                      component_rate number       path '$.RATE'
              )
        ) loop
            if trim(e.component) is null then
                add_error(l_errors, 'NON_MERCH_COSTS.COMPONENT', 'REQUIRED',
                    'COMPONENT is required on non-merchandise cost row ' || e.rn || '.');
            end if;
            if e.component_rate is null or e.component_rate < 0 then
                add_error(l_errors, 'NON_MERCH_COSTS.RATE', 'POSITIVE_VALUE_REQUIRED',
                    'RATE is required and cannot be negative on non-merchandise cost row ' || e.rn || '.');
            end if;
        end loop;

        if trim(l_department) is not null
           and not has_master('DEPARTMENT', trim(l_department)) then
            add_error(l_errors, 'DEPARTMENT', 'UNKNOWN_DEPARTMENT',
                'Department ' || l_department || ' is not known to this tenant.');
        end if;

        if trim(l_department) is not null and trim(l_class) is not null
           and not has_master('CLASS', trim(l_class), trim(l_department)) then
            add_error(l_errors, 'CLASS', 'UNKNOWN_CLASS',
                'Class ' || l_class || ' is not known under department ' || l_department || '.');
        end if;

        if trim(l_department) is not null and trim(l_class) is not null and trim(l_subclass) is not null
           and not has_master('SUBCLASS', trim(l_subclass),
                              trim(l_department) || '.' || trim(l_class)) then
            add_error(l_errors, 'SUBCLASS', 'UNKNOWN_SUBCLASS',
                'Subclass ' || l_subclass || ' is not known under ' || l_department || '.' || l_class || '.');
        end if;

        if trim(l_supplier) is not null
           and not has_master('SUPPLIER_SVC', trim(l_supplier)) then
            add_error(l_errors, 'SUPPLIER', 'UNKNOWN_SUPPLIER',
                'Supplier ' || l_supplier || ' is not known to this tenant.');
        end if;

        if trim(l_country) is not null
           and not has_master('COUNTRY', upper(trim(l_country))) then
            add_error(l_errors, 'ORIGIN_COUNTRY', 'UNKNOWN_COUNTRY',
                'Country ' || l_country || ' is not known to this tenant.');
        end if;

        if trim(l_currency) is not null
           and not has_master('CURRENCY', upper(trim(l_currency))) then
            add_error(l_errors, 'CURRENCY_CODE', 'UNKNOWN_CURRENCY',
                'Currency ' || l_currency || ' is not known to this tenant.');
        end if;

        -- The colour is a differentiator ID, not a name. Front ends send the
        -- tenant's own code; there is no description to translate.
        if trim(l_colour) is not null
           and not has_master('DIFF_C', trim(l_colour)) then
            add_error(l_errors, 'COLOUR', 'UNKNOWN_COLOUR',
                'Colour ' || l_colour || ' is not a differentiator on this tenant.');
        end if;

        for v in (
            select sku_size, sku_width
              from json_table(p_payload, '$.SIZE_CURVE_DETAIL[*]'
                  columns
                      sku_size varchar2(60) path '$.SKU_SIZE' null on error,
                      sku_width varchar2(60) path '$.SKU_WIDTH' null on error
              )
        ) loop
            -- Likewise a differentiator ID. This is what removed the last reason
            -- to keep MAP: eight size descriptions are ambiguous on this tenant
            -- ("16" is three different differentiators), and a code never is.
            if v.sku_size is null then
                add_error(l_errors, 'SIZE_CURVE_DETAIL.SKU_SIZE', 'REQUIRED',
                    'SKU_SIZE is required.');
            elsif not has_master('DIFF_S', trim(v.sku_size)) then
                add_error(l_errors, 'SIZE_CURVE_DETAIL.SKU_SIZE', 'UNKNOWN_SIZE',
                    'Size ' || v.sku_size || ' is not a differentiator on this tenant.');
            end if;

        end loop;

        declare
            l_brand varchar2(120) := json_value(p_payload, '$.BRAND' returning varchar2(120) null on error);
            l_brands number;
        begin
            if trim(l_brand) is not null then
                select count(*) into l_brands from ie_mfcs_ref_master_data where data_type = 'BRAND';
                if l_brands > 0 then
                    select count(*)
                      into l_count
                      from ie_mfcs_ref_master_data
                     where data_type = 'BRAND'
                       and data_code = l_brand;
                    if l_count = 0 then
                        add_error(l_errors, 'BRAND', 'UNKNOWN_BRAND',
                            'Brand ' || l_brand || ' is not defined on this tenant.');
                    end if;
                end if;
            end if;
        end;

        if l_errors.get_size > 0 then
            o_errors := l_errors.to_clob;
            return false;
        end if;

        o_errors := '[]';
        return true;
    end;
end ie_mfcs_validation;
/

-- ==== 20_packages/06_ie_mfcs_payload.sql

-- Reads the Office document and builds each MFCS request payload.
--
-- The whole MFCS write contract in one place: every request body the
-- orchestrator sends is built here, from the stored Office document plus
-- IE_MFCS_CFG_SETTING defaults. ie_mfcs_orchestrator calls build_request
-- statically, so a missing mapper is a compile error, not a runtime surprise.
--
-- MFCS's read and write vocabularies disagree (the order feed says
-- physicalQuantityOrdered / originCountryId where the write wants
-- quantityOrdered / originCountry); the mappers here speak the write
-- vocabulary only.

create or replace package ie_mfcs_payload authid definer as
    function build_request(
        p_action_request_id in varchar2,
        p_mapper_name       in varchar2
    ) return clob;

    -- Readers for the stored Office request document. These moved here from
    -- mapping_pkg, which existed only to switch between the mock and
    -- real mappers and became a forwarding layer once the simulators were removed.
    function source_system(p_payload in clob) return varchar2;
    function source_style_ref(p_payload in clob) return varchar2;

    -- The style's MFCS item number when the caller chose it, null when it did
    -- not. Null is what puts the request on the reserve path, so this is the one
    -- test that decides which way item numbering goes.
    function document_item_number(p_payload in clob) return varchar2;

    -- The type MFCS is to be told, which follows from who chose the number.
    -- MANL when the caller supplied one - the only type a caller can supply,
    -- since ITEM demands nine characters with a valid Oracle check digit and
    -- refuses an invented number. ITEM otherwise, because the numbers then came
    -- from itemNumbers/reserve, which issues that type.
    function document_item_number_type(p_payload in clob) return varchar2;

    -- The style's MFCS description. The document's own ITEM_DESCRIPTION when it
    -- carries one, otherwise SOURCE_STYLE_REF, which is what every document
    -- written before this field existed relies on.
    function style_description(p_payload in clob) return varchar2;

    -- One SKU's MFCS description. The row's own ITEM_DESCRIPTION when it carries
    -- one, otherwise the style description with the size differentiator appended,
    -- which is the derivation this layer has always used.
    function sku_description(
        p_payload          in clob,
        p_item_description in varchar2,
        p_sku_size         in varchar2
    ) return varchar2;
    function source_order_ref(p_payload in clob) return varchar2;
    function user_id(p_payload in clob) return varchar2;
    function request_payload(p_action_request_id in varchar2) return clob;

    -- Exposed so the orchestrator can read one request field without a second
    -- JSON-reading implementation.
    function string_value(p_payload in clob, p_name in varchar2) return varchar2;

    -- A delivery location as the virtual warehouse MFCS wants, derived from the
    -- tenant's warehouse feed. Public because the order-line planner needs the
    -- same answer the order mapper gets.
    function virtual_location(p_location in varchar2) return varchar2;

    -- One row of the inbound document's SIZE_CURVE_DETAIL array. Every reader of
    -- the size curve - here and in the orchestrator - sees this shape; the
    -- json_table projection behind it is defined once (c_size_curve, in the
    -- body), so a column added to the curve lands in exactly one place.
    type t_size_curve_row is record (
        rn                 pls_integer,
        source_variant_ref varchar2(120),
        sku_size           varchar2(60),
        sku_width          varchar2(60),
        sku_id             varchar2(30),
        sku_qty            number,
        -- The SKU's MFCS item number when the caller chose it. Distinct from
        -- SKU_ID, which names a SKU MFCS already holds: SKU_ID is a reference on
        -- a modify, ITEM_NUMBER is an assignment on a create, and validation
        -- keeps them from ever arriving together.
        item_number        varchar2(30),
        -- The SKU's MFCS description when the caller composed it. Same argument
        -- as ITEM_NUMBER: a caller that builds "MODEL Colour Size" from its own
        -- data should send the result, not have this layer guess at it from a
        -- style reference and a differentiator id.
        item_description   varchar2(250)
    );
    type t_size_curve is table of t_size_curve_row index by pls_integer;

    -- The single definition of the size-curve projection, public so the
    -- orchestrator loops the same cursor instead of keeping a copy. Ten
    -- readers used to carry their own json_table of this array; a column
    -- added to the curve is now added here and nowhere else.
    cursor c_size_curve(cp_payload clob) is
        select rn, source_variant_ref, sku_size, sku_width, sku_id, sku_qty,
               item_number, item_description
          from json_table(cp_payload, '$.SIZE_CURVE_DETAIL[*]'
              columns
                  rn                 for ordinality,
                  source_variant_ref varchar2(120) path '$.SOURCE_VARIANT_REF',
                  sku_size           varchar2(60)  path '$.SKU_SIZE',
                  sku_width          varchar2(60)  path '$.SKU_WIDTH',
                  sku_id             varchar2(30)  path '$.SKU_ID',
                  sku_qty            number        path '$.SKU_QTY',
                  item_number        varchar2(30)  path '$.ITEM_NUMBER',
                  item_description   varchar2(250) path '$.ITEM_DESCRIPTION'
          );

    -- Barcodes hang off a size-curve row, so they cannot ride in c_size_curve
    -- without multiplying it: a SKU with two barcodes would become two SKUs.
    -- They get their own projection, carrying the parent row's identity down so
    -- the reference-item builder can resolve which SKU each barcode belongs to.
    --
    -- The where clause is not a nicety. json_table's nested path is an outer
    -- join: a size-curve row with no SKU_UPCS still produces one row, with every
    -- nested column null. Without the filter a SKU without barcodes would build a
    -- level-3 item whose item number is null and send it to the tenant.
    cursor c_sku_upcs(cp_payload clob) is
        select rn, source_variant_ref, sku_id, sku_size, sku_width, item_description,
               upc_rn, upc, upc_type, primary_yn
          from json_table(cp_payload, '$.SIZE_CURVE_DETAIL[*]'
              columns
                  rn                 for ordinality,
                  source_variant_ref varchar2(120) path '$.SOURCE_VARIANT_REF',
                  sku_id             varchar2(30)  path '$.SKU_ID',
                  sku_size           varchar2(60)  path '$.SKU_SIZE',
                  sku_width          varchar2(60)  path '$.SKU_WIDTH',
                  item_description   varchar2(250) path '$.ITEM_DESCRIPTION',
                  nested path '$.SKU_UPCS[*]'
                      columns (
                          upc_rn     for ordinality,
                          upc        varchar2(30) path '$.UPC',
                          upc_type   varchar2(10) path '$.UPC_TYPE',
                          primary_yn varchar2(1)  path '$.PRIMARY_YN'
                      )
          )
         where upc is not null;

    -- UDAs are style-level. SKUs inherit them from the style, so there is
    -- deliberately no SKU-level slot in the document; the mapper writes the same
    -- set to the parent and to every child.
    --
    -- The document puts its value in whichever of the three fields suits the UDA.
    -- Which one MFCS actually reads is decided by displayType, which comes from
    -- master data rather than from the document.
    -- Seasons, images and tariff codes. Style-level like UDAs, and for the same
    -- reason: a real Office item carries them identically on the style and on
    -- every SKU, so there is no SKU-level slot to fill in.
    cursor c_style_seasons(cp_payload clob) is
        select rn, season_id, phase_id, sequence_no
          from json_table(cp_payload, '$.STYLE_SEASONS[*]'
              columns
                  rn          for ordinality,
                  season_id   number path '$.SEASON_ID',
                  phase_id    number path '$.PHASE_ID',
                  sequence_no number path '$.SEQUENCE_NO'
          )
         where season_id is not null;

    cursor c_style_images(cp_payload clob) is
        select rn, image_name, image_address, image_description,
               image_type, primary_yn, display_priority
          from json_table(cp_payload, '$.STYLE_IMAGES[*]'
              columns
                  rn                for ordinality,
                  image_name        varchar2(120) path '$.IMAGE_NAME',
                  image_address     varchar2(255) path '$.IMAGE_ADDRESS',
                  image_description varchar2(40)  path '$.IMAGE_DESCRIPTION',
                  image_type        varchar2(6)   path '$.IMAGE_TYPE',
                  primary_yn        varchar2(1)   path '$.PRIMARY_YN',
                  display_priority  number        path '$.DISPLAY_PRIORITY'
          )
         where image_name is not null;

    -- Assessments are not carried. The tenant's own rows have componentId
    -- DTY7AGB against computationValueBase VFDGB with duty and expense flags,
    -- and nobody here knows what those should be for a new style. The tariff
    -- code itself is useful without them.
    cursor c_style_hts(cp_payload clob) is
        select rn, hts, import_country, origin_country, effect_from, effect_to
          from json_table(cp_payload, '$.STYLE_HTS[*]'
              columns
                  rn             for ordinality,
                  hts            varchar2(25) path '$.HTS',
                  import_country varchar2(3)  path '$.IMPORT_COUNTRY',
                  origin_country varchar2(3)  path '$.ORIGIN_COUNTRY',
                  effect_from    varchar2(20) path '$.EFFECT_FROM',
                  effect_to      varchar2(20) path '$.EFFECT_TO'
          )
         where hts is not null;

    cursor c_style_udas(cp_payload clob) is
        select rn, uda_id, uda_type, uda_value, uda_text, uda_date
          from json_table(cp_payload, '$.STYLE_UDAS[*]'
              columns
                  rn        for ordinality,
                  uda_id    number        path '$.UDA_ID',
                  uda_type  varchar2(2)   path '$.UDA_TYPE',
                  uda_value varchar2(30)  path '$.UDA_VALUE',
                  uda_text  varchar2(250) path '$.UDA_TEXT',
                  uda_date  varchar2(30)  path '$.UDA_DATE'
          )
         where uda_id is not null;

    -- The size curve of any document carrying SIZE_CURVE_DETAIL - the stored
    -- request, or an MFCS response echoing the same shape back.
    function size_curve(p_payload in clob) return t_size_curve;

    -- The MFCS SKU behind one size-curve row: the row's own SKU_ID when the
    -- document carries it, otherwise the IE_MFCS_MAP_ENTITY row filed under the same
    -- source references - by an earlier request, or by ENSURE_STYLE_SKUS when
    -- it read or created the child. Public because the order-line sync needs
    -- the same resolution the mappers use; two resolutions could disagree.
    function resolve_sku(
        p_payload            in clob,
        p_source_variant_ref in varchar2,
        p_payload_sku        in varchar2
    ) return varchar2;

    -- A child this layer has decided to create: the reserved item number plus
    -- the resolved differentiators the gap analysis compared against.
    type t_generated_child is record (
        item               varchar2(30),
        sku_size           varchar2(60),
        size_diff          varchar2(120),
        colour_diff        varchar2(120),
        source_variant_ref varchar2(120),
        sku_width          varchar2(60)
    );
    type t_generated_children is table of t_generated_child index by pls_integer;

    -- Everything the generated-child builders need: the parent's identity and
    -- attributes as the tenant reports them (via ie_mfcs_sku.style_attributes), and
    -- the children to create. A typed record rather than a JSON document on
    -- purpose - a misspelled field here is a compile error, where a misspelled
    -- JSON key would be a silent null, which is the failure mode this whole
    -- layer is built to avoid.
    type t_child_plan is record (
        style                varchar2(30),
        dept                 number,
        class                number,
        subclass             number,
        original_retail      number,
        cost_zone_group_id   number,
        item_description     varchar2(250),
        short_description    varchar2(120),
        standard_uom         varchar2(10),
        store_order_multiple varchar2(1),
        supplier             number,
        unit_cost            number,
        origin_country       varchar2(3),
        children             t_generated_children
    );

    -- One purchase-order line as the sync step wants it to be (or, for a
    -- cancellation, as the order currently has it).
    type t_order_line is record (
        item          varchar2(30),
        quantity      number,
        -- The order's current quantity for the line, when it already has one.
        -- A reduction needs a reason: MFCS wants a cancel code on the quantity
        -- that goes away, distinct from a full-line cancellation.
        prev_quantity number
    );
    type t_order_lines is table of t_order_line index by pls_integer;

    -- What SYNC_ORDER_LINES decided after reading the order back:
    -- lines to update in place, lines to add, and this style's lines to cancel.
    -- Built by the orchestrator from tenant state; typed for the same reason as
    -- t_child_plan - a misspelled field should not compile.
    type t_order_line_plan is record (
        order_no           varchar2(30),
        location           number,
        location_type      varchar2(1),
        origin_country     varchar2(3),
        unit_cost          number,
        supplier_pack_size number,
        earliest_ship_date varchar2(20),
        latest_ship_date   varchar2(20),
        updates            t_order_lines,
        creates            t_order_lines,
        cancels            t_order_lines
    );

    -- purchaseOrder/details payloads. Update and create share a line shape;
    -- cancel goes through details/update with cancelInd and the tenant's own
    -- cancel code (code type ORCA - 'S' is literally "Colour/Location
    -- Switched"). purchaseOrders/update ignores its details array on this
    -- tenant, which is why these exist at all.
    function order_details_update_request(p_plan in t_order_line_plan) return clob;
    function order_details_create_request(p_plan in t_order_line_plan) return clob;
    function order_details_cancel_request(p_plan in t_order_line_plan) return clob;

    -- Payloads for children this layer decides at run time to create, as opposed
    -- to ones the inbound document names. The other item builders walk the whole
    -- size curve, which is right for a new style and wrong when only some of its
    -- combinations are missing: re-sending the rest either does nothing or makes
    -- a second child on the same diff pair. These take the missing subset only.
    -- Not reachable through build_request - a mapper name cannot carry the plan.
    function generated_child_create_request(
        p_action_request_id in varchar2,
        p_plan              in t_child_plan
    ) return clob;

    function generated_child_sourcing_request(
        p_action_request_id in varchar2,
        p_plan              in t_child_plan
    ) return clob;

    function generated_child_com_request(
        p_action_request_id in varchar2,
        p_plan              in t_child_plan
    ) return clob;

    function generated_child_approval_request(
        p_action_request_id in varchar2,
        p_plan              in t_child_plan
    ) return clob;
end ie_mfcs_payload;
/

create or replace package body ie_mfcs_payload as

    function size_curve(p_payload in clob) return t_size_curve is
        l_rows t_size_curve;
        l_i    pls_integer := 0;
    begin
        for v in c_size_curve(p_payload) loop
            l_i := l_i + 1;
            l_rows(l_i).rn := v.rn;
            l_rows(l_i).source_variant_ref := v.source_variant_ref;
            l_rows(l_i).sku_size := v.sku_size;
            l_rows(l_i).sku_width := v.sku_width;
            l_rows(l_i).sku_id := v.sku_id;
            l_rows(l_i).sku_qty := v.sku_qty;
        end loop;
        return l_rows;
    end;

    function request_payload(p_action_request_id in varchar2) return clob is
        l_payload clob;
    begin
        select request_payload
          into l_payload
          from ie_mfcs_prd_request
         where action_request_id = p_action_request_id;

        return l_payload;
    end;

    function source_system(p_payload in clob) return varchar2 is
        l_value varchar2(60);
    begin
        select json_value(p_payload, '$.SOURCE_SYSTEM' returning varchar2(60) null on error)
          into l_value
          from dual;
        return l_value;
    end;

    function source_style_ref(p_payload in clob) return varchar2 is
        l_value varchar2(120);
    begin
        select json_value(p_payload, '$.SOURCE_STYLE_REF' returning varchar2(120) null on error)
          into l_value
          from dual;
        return l_value;
    end;

    function document_item_number(p_payload in clob) return varchar2 is
        l_value varchar2(30);
    begin
        select trim(json_value(p_payload, '$.ITEM_NUMBER' returning varchar2(30) null on error))
          into l_value
          from dual;
        return l_value;
    end;

    function document_item_number_type(p_payload in clob) return varchar2 is
        l_type varchar2(10);
    begin
        select upper(trim(json_value(p_payload, '$.ITEM_NUMBER_TYPE' returning varchar2(10) null on error)))
          into l_type
          from dual;
        -- Defaulted rather than required, so every document written before this
        -- field existed still resolves to the type its numbers actually are.
        return nvl(l_type, 'ITEM');
    end;

    function style_description(p_payload in clob) return varchar2 is
        l_desc varchar2(250);
    begin
        select coalesce(
                   trim(json_value(p_payload, '$.ITEM_DESCRIPTION' returning varchar2(250) null on error)),
                   json_value(p_payload, '$.SOURCE_STYLE_REF' returning varchar2(250) null on error))
          into l_desc
          from dual;
        return substr(l_desc, 1, 250);
    end;

    function sku_description(
        p_payload          in clob,
        p_item_description in varchar2,
        p_sku_size         in varchar2
    ) return varchar2 is
    begin
        if trim(p_item_description) is not null then
            return substr(trim(p_item_description), 1, 250);
        end if;
        return substr(trim(style_description(p_payload) || ' ' || p_sku_size), 1, 250);
    end;

    function source_order_ref(p_payload in clob) return varchar2 is
        l_value varchar2(120);
    begin
        select json_value(p_payload, '$.SOURCE_ORDER_REF' returning varchar2(120) null on error)
          into l_value
          from dual;
        return l_value;
    end;

    function user_id(p_payload in clob) return varchar2 is
        l_value varchar2(120);
    begin
        select coalesce(
                   json_value(p_payload, '$.USER_ID' returning varchar2(120) null on error),
                   json_value(p_payload, '$.APPROVED_BY' returning varchar2(120) null on error),
                   'INTEGRATION'
               )
          into l_value
          from dual;
        return l_value;
    end;

    function payload(p_action_request_id in varchar2) return clob is
        l_payload clob;
    begin
        select request_payload
          into l_payload
          from ie_mfcs_prd_request
         where action_request_id = p_action_request_id;
        return l_payload;
    end;

    function string_value(p_payload in clob, p_name in varchar2) return varchar2 is
    begin
        return json_object_t.parse(p_payload).get_string(p_name);
    end;

    function number_value(p_payload in clob, p_name in varchar2) return number is
    begin
        return json_object_t.parse(p_payload).get_number(p_name);
    end;

    -- A delivery location, as the virtual warehouse MFCS wants.
    --
    -- The one translation that survived MAP's retirement, because it is not a
    -- naming difference: item ranging is refused against a physical warehouse at
    -- hierarchy level W, and a caller may legitimately think in physical
    -- locations. It now derives from the tenant's own warehouse feed - the row
    -- for 1927 carries primaryVirtualWarehouse 19271 - rather than from a
    -- hand-maintained MAP.ORDER_LOCATION entry.
    --
    -- Passes the value straight through when it is already virtual, or when the
    -- warehouse is unknown to master data. A caller sending the virtual warehouse
    -- directly, which is what the console does, is unaffected either way.
    function virtual_location(p_location in varchar2) return varchar2 is
        l_virtual varchar2(120);
    begin
        if p_location is null then
            return null;
        end if;
        select max(json_value(attributes, '$.primaryVirtualWarehouse'))
          into l_virtual
          from ie_mfcs_ref_master_data
         where data_type = 'WAREHOUSE_SVC'
           and data_code = p_location;
        return nvl(l_virtual, p_location);
    end;

    -- The operations that write to a style MFCS already holds. Their item payloads
    -- are updates, which carry only what is being set; a create carries the whole
    -- structural record. CREATE_ALL is a create, because it makes the style itself.
    function targets_existing_style(p_operation in varchar2) return boolean is
    begin
        return p_operation in ('MODIFY_STYLE', 'CREATE_ORDER', 'MODIFY_ORDER');
    end;

    function request_style(p_action_request_id in varchar2) return varchar2 is
        l_style varchar2(30);
    begin
        select style_no into l_style
          from ie_mfcs_prd_request
         where action_request_id = p_action_request_id;

        return l_style;
    end;

    function request_order(p_action_request_id in varchar2) return varchar2 is
        l_order varchar2(30);
    begin
        select order_no into l_order
          from ie_mfcs_prd_request
         where action_request_id = p_action_request_id;
        return l_order;
    end;

    function resolve_sku(
        p_payload            in clob,
        p_source_variant_ref in varchar2,
        p_payload_sku        in varchar2
    ) return varchar2 is
        l_sku varchar2(30) := p_payload_sku;
        l_source_system varchar2(60);
        l_source_style_ref varchar2(120);
    begin
        if l_sku is not null then
            return l_sku;
        end if;

        select json_value(p_payload, '$.SOURCE_SYSTEM' returning varchar2(60)),
               json_value(p_payload, '$.SOURCE_STYLE_REF' returning varchar2(120))
          into l_source_system, l_source_style_ref
          from dual;

        select max(mfcs_sku_no)
          into l_sku
          from ie_mfcs_map_entity
         where source_system = l_source_system
           and source_style_ref = l_source_style_ref
           and source_variant_ref = p_source_variant_ref;

        return l_sku;
    end;

    function item_number_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_root json_object_t := json_object_t();
        l_count number;
    begin
        -- One number per child plus one for the style itself.
        l_count := size_curve(l_payload).count + 1;
        l_root.put('itemNumberType', 'ITEM');
        l_root.put('quantity', l_count);
        l_root.put('daysUntilExpiry', 14);
        return l_root.to_clob;
    end;

    procedure append_parent_item(
        p_items       in out nocopy json_array_t,
        p_operation   in varchar2,
        p_style       in varchar2,
        p_department  in number,
        p_class       in number,
        p_subclass    in number,
        p_retail      in number,
        p_source_ref  in varchar2,
        p_color       in varchar2,
        -- Defaulted so a caller that has no brand to give does not have to say so.
        p_brand       in varchar2 default null,
        -- Defaulted to the reserve path's type, so a caller that chose no number
        -- does not have to say which kind of number it did not choose.
        p_item_number_type in varchar2 default 'ITEM'
    ) is
        l_cost_zone_group_id number :=
            to_number(ie_mfcs_config.get_config('MFCS_COST_ZONE_GROUP_ID', '2000'));
        l_parent_diff1 varchar2(80) :=
            ie_mfcs_config.get_config('MFCS_PARENT_DIFF1_GROUP', 'RMS_ALL_C');
        l_parent_diff2 varchar2(80) :=
            ie_mfcs_config.get_config('MFCS_PARENT_DIFF2_GROUP', 'ALL');
        l_store_order_multiple varchar2(1) :=
            ie_mfcs_config.get_config('MFCS_STORE_ORDER_MULTIPLE', 'E');
        l_item json_object_t := json_object_t();
    begin
        l_item.put('item', p_style);
        l_item.put('itemDescription', substr(p_source_ref, 1, 250));
        l_item.put('shortDescription', substr(p_source_ref, 1, 120));
        l_item.put('dataLoadingDestination', 'RMS');
        -- Omitted rather than sent null when the document carries no brand: the
        -- update services treat a null as a value and would clear an existing one.
        if p_brand is not null then
            l_item.put('brandName', p_brand);
        end if;
        -- storeOrderMultiple is not optional on an update, even one that only touches
        -- descriptions: items/update answers a payload without it with
        -- "Field must be entered.Field: STORE_ORD_MULT ... CORESVC_ITEM.PROCESS_IM".
        -- Proven live, which is why it sits outside the create-only block.
        l_item.put('storeOrderMultiple', l_store_order_multiple);
        if not targets_existing_style(p_operation) then
            l_item.put('itemNumberType', p_item_number_type);
            l_item.put('itemLevel', 1);
            l_item.put('tranLevel', 2);
            l_item.put('dept', p_department);
            l_item.put('class', p_class);
            l_item.put('subclass', p_subclass);
            l_item.put('status', 'W');
            l_item.put('approveInd', 'N');
            l_item.put('standardUom', 'EA');
            l_item.put('merchandiseInd', 'Y');
            l_item.put('inventoryInd', 'Y');
            l_item.put('sellableInd', 'Y');
            l_item.put('orderableInd', 'Y');
            l_item.put('originalRetail', p_retail);
            l_item.put('costZoneGroupId', l_cost_zone_group_id);
            l_item.put('diff1', l_parent_diff1);
            l_item.put('diff1Type', 'C');
            l_item.put('diff2', l_parent_diff2);
            l_item.put('diff2Type', 'S');
        end if;
        p_items.append(l_item);
    end;

    procedure append_child_items(
        p_items       in out nocopy json_array_t,
        p_payload     in clob,
        p_operation   in varchar2,
        p_style       in varchar2,
        p_department  in number,
        p_class       in number,
        p_subclass    in number,
        p_retail      in number,
        p_source_ref  in varchar2,
        p_color       in varchar2
    ) is
        l_cost_zone_group_id number :=
            to_number(ie_mfcs_config.get_config('MFCS_COST_ZONE_GROUP_ID', '2000'));
        l_store_order_multiple varchar2(1) :=
            ie_mfcs_config.get_config('MFCS_STORE_ORDER_MULTIPLE', 'E');
        l_item json_object_t;
        l_sku varchar2(30);
        l_item_number_type varchar2(10) := document_item_number_type(p_payload);
    begin
        for v in c_size_curve(p_payload) loop
            l_sku := resolve_sku(p_payload, v.source_variant_ref, v.sku_id);
            l_item := json_object_t();
            l_item.put('item', l_sku);
            l_item.put('itemDescription',
                sku_description(p_payload, v.item_description, v.sku_size));
            l_item.put('shortDescription', substr(p_source_ref, 1, 120));
            l_item.put('dataLoadingDestination', 'RMS');
            -- Required on update as well as create; see append_parent_item.
            l_item.put('storeOrderMultiple', l_store_order_multiple);
            if not targets_existing_style(p_operation) then
                l_item.put('itemParent', p_style);
                l_item.put('itemNumberType', l_item_number_type);
                l_item.put('itemLevel', 2);
                l_item.put('tranLevel', 2);
                l_item.put('dept', p_department);
                l_item.put('class', p_class);
                l_item.put('subclass', p_subclass);
                l_item.put('status', 'W');
                l_item.put('approveInd', 'N');
                l_item.put('standardUom', 'EA');
                l_item.put('merchandiseInd', 'Y');
                l_item.put('inventoryInd', 'Y');
                l_item.put('sellableInd', 'Y');
                l_item.put('orderableInd', 'Y');
                l_item.put('originalRetail', p_retail);
                l_item.put('costZoneGroupId', l_cost_zone_group_id);
                l_item.put('diff1', p_color);
                l_item.put('diff1Type', 'C');
                l_item.put('diff2', v.sku_size);
                l_item.put('diff2Type', 'S');
            end if;
            p_items.append(l_item);
        end loop;
    end;

    procedure item_create_context(
        p_action_request_id in varchar2,
        o_payload           out clob,
        o_operation         out varchar2,
        o_style             out varchar2,
        o_department        out number,
        o_class             out number,
        o_subclass          out number,
        o_retail            out number,
        o_source_ref        out varchar2,
        o_color             out varchar2
    ) is
    begin
        o_payload := payload(p_action_request_id);
        o_style := request_style(p_action_request_id);
        select json_value(o_payload, '$.OPERATION_NAME' returning varchar2(30)),
               json_value(o_payload, '$.DEPARTMENT' returning number),
               json_value(o_payload, '$.CLASS' returning number),
               json_value(o_payload, '$.SUBCLASS' returning number),
               json_value(o_payload, '$.RETAIL_PRICE' returning number),
               json_value(o_payload, '$.COLOUR' returning varchar2(10))
          into o_operation, o_department, o_class, o_subclass, o_retail, o_color
          from dual;

        -- The description the items are created with, which is the document's own
        -- ITEM_DESCRIPTION when it sent one and SOURCE_STYLE_REF when it did not.
        -- Resolved here so the parent create, the child create and the approve
        -- step cannot disagree about what a style is called.
        o_source_ref := style_description(o_payload);
    end;

    function parent_item_create_request(p_action_request_id in varchar2) return clob is
        l_payload clob;
        l_operation varchar2(30);
        l_style varchar2(30);
        l_department number;
        l_class number;
        l_subclass number;
        l_retail number;
        l_source_ref varchar2(120);
        l_color varchar2(10);
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
    begin
        item_create_context(p_action_request_id, l_payload, l_operation, l_style, l_department, l_class, l_subclass, l_retail, l_source_ref, l_color);
        append_parent_item(l_items, l_operation, l_style, l_department, l_class, l_subclass, l_retail, l_source_ref, l_color,
            json_value(l_payload, '$.BRAND' returning varchar2(120) null on error),
            document_item_number_type(l_payload));
        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function child_item_create_request(p_action_request_id in varchar2) return clob is
        l_payload clob;
        l_operation varchar2(30);
        l_style varchar2(30);
        l_department number;
        l_class number;
        l_subclass number;
        l_retail number;
        l_source_ref varchar2(120);
        l_color varchar2(10);
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
    begin
        item_create_context(p_action_request_id, l_payload, l_operation, l_style, l_department, l_class, l_subclass, l_retail, l_source_ref, l_color);
        append_child_items(l_items, l_payload, l_operation, l_style, l_department, l_class, l_subclass, l_retail, l_source_ref, l_color);
        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function item_create_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_operation varchar2(30);
        l_style varchar2(30) := request_style(p_action_request_id);
        l_department number;
        l_class number;
        l_subclass number;
        l_retail number;
        l_source_ref varchar2(120);
        l_color varchar2(10);
        l_cost_zone_group_id number :=
            to_number(ie_mfcs_config.get_config('MFCS_COST_ZONE_GROUP_ID', '2000'));
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
    begin
        select json_value(l_payload, '$.OPERATION_NAME' returning varchar2(30)),
               json_value(l_payload, '$.DEPARTMENT' returning number),
               json_value(l_payload, '$.CLASS' returning number),
               json_value(l_payload, '$.SUBCLASS' returning number),
               json_value(l_payload, '$.RETAIL_PRICE' returning number),
               json_value(l_payload, '$.SOURCE_STYLE_REF' returning varchar2(120)),
               json_value(l_payload, '$.COLOUR' returning varchar2(10))
          into l_operation, l_department, l_class, l_subclass, l_retail, l_source_ref, l_color
          from dual;

        append_parent_item(l_items, l_operation, l_style, l_department, l_class, l_subclass, l_retail, l_source_ref, l_color,
            json_value(l_payload, '$.BRAND' returning varchar2(120) null on error),
            document_item_number_type(l_payload));
        append_child_items(l_items, l_payload, l_operation, l_style, l_department, l_class, l_subclass, l_retail, l_source_ref, l_color);

        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function supplier_payload(
        p_item     in varchar2,
        p_supplier in number,
        p_cost     in number,
        p_country  in varchar2
    ) return json_object_t is
        l_item json_object_t := json_object_t();
        l_country_node json_object_t;
        l_suppliers json_array_t;
        l_countries json_array_t;
        l_supplier_node json_object_t;
    begin
        l_country_node := json_object_t();
        l_country_node.put('originCountry', p_country);
        l_country_node.put('primaryCountryInd', 'Y');
        l_country_node.put('unitCost', p_cost);
        l_country_node.put('defaultUop', ie_mfcs_config.get_config('MFCS_DEFAULT_UOP', 'EA'));
        l_country_node.put('costUom', ie_mfcs_config.get_config('MFCS_COST_UOM', 'EA'));
        l_country_node.put('supplierPackSize', to_number(ie_mfcs_config.get_config('MFCS_SUPPLIER_PACK_SIZE', '1')));
        l_country_node.put('innerPackSize', to_number(ie_mfcs_config.get_config('MFCS_INNER_PACK_SIZE', '1')));
        l_country_node.put('purchaseType', to_number(ie_mfcs_config.get_config('MFCS_PURCHASE_TYPE', '0')));
        l_countries := json_array_t();
        l_countries.append(l_country_node);

        l_supplier_node := json_object_t();
        l_supplier_node.put('supplier', p_supplier);
        l_supplier_node.put('primarySupplierInd', 'Y');
        -- The create service defaults this; the update service demands it, with
        -- "This column should not be null.Field: DIRECT_SHIP_IND ...
        -- CORESVC_ITEM.PROCESS_IS". Sent on both paths because the tenant stores N
        -- on every item anyway, so the create payload was only ever relying on luck.
        l_supplier_node.put('directShipInd', ie_mfcs_config.get_config('MFCS_DIRECT_SHIP_IND', 'N'));
        -- The packaging names. suppliers/update refuses without innerName, and there
        -- is no reason to think it stops there, so all three go every time rather
        -- than one per failed round trip. The values are the tenant's own: code types
        -- INRN, CASN and PALN, loaded into master data by ie_mfcs_master_data.refresh_all.
        -- EA rather than the spec's INR example because the pack sizes here are 1.
        l_supplier_node.put('innerName', ie_mfcs_config.get_config('MFCS_INNER_NAME', 'EA'));
        l_supplier_node.put('caseName', ie_mfcs_config.get_config('MFCS_CASE_NAME', 'CS'));
        l_supplier_node.put('palletName', ie_mfcs_config.get_config('MFCS_PALLET_NAME', 'PAL'));
        l_supplier_node.put('countryOfSourcing', l_countries);
        l_suppliers := json_array_t();
        l_suppliers.append(l_supplier_node);

        l_item.put('item', p_item);
        l_item.put('dataLoadingDestination', 'RMS');
        l_item.put('supplier', l_suppliers);
        return l_item;
    end;

    function parent_item_sourcing_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_supplier number;
        l_cost number;
        l_country varchar2(3);
    begin
        select json_value(l_payload, '$.SUPPLIER' returning number),
               json_value(l_payload, '$.UNIT_COST' returning number),
               json_value(l_payload, '$.ORIGIN_COUNTRY' returning varchar2(3))
          into l_supplier, l_cost, l_country
          from dual;

        l_items.append(supplier_payload(request_style(p_action_request_id), l_supplier, l_cost, l_country));
        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function item_sourcing_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_supplier number;
        l_cost number;
        l_country varchar2(3);
        l_sku varchar2(30);
    begin
        select json_value(l_payload, '$.SUPPLIER' returning number),
               json_value(l_payload, '$.UNIT_COST' returning number),
               json_value(l_payload, '$.ORIGIN_COUNTRY' returning varchar2(3))
          into l_supplier, l_cost, l_country
          from dual;

        for v in c_size_curve(l_payload) loop
            l_sku := resolve_sku(l_payload, v.source_variant_ref, v.sku_id);
            l_items.append(supplier_payload(l_sku, l_supplier, l_cost, l_country));
        end loop;

        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function child_item_sourcing_request(p_action_request_id in varchar2) return clob is
    begin
        return item_sourcing_request(p_action_request_id);
    end;

    function item_country_of_manufacture_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_item json_object_t;
        l_supplier_node json_object_t;
        l_manufacture_node json_object_t;
        l_suppliers json_array_t;
        l_manufacturers json_array_t;
        l_supplier number;
        l_manufacturer_country varchar2(3) :=
            ie_mfcs_config.get_config('MFCS_MANUFACTURER_COUNTRY', 'VN');

        procedure append_item(p_item in varchar2) is
        begin
            l_manufacture_node := json_object_t();
            l_manufacture_node.put('manufacturerCountry', l_manufacturer_country);
            l_manufacture_node.put('primaryManufacturerCountryInd', 'Y');
            l_manufacturers := json_array_t();
            l_manufacturers.append(l_manufacture_node);

            l_supplier_node := json_object_t();
            l_supplier_node.put('supplier', l_supplier);
            l_supplier_node.put('countryOfManufacture', l_manufacturers);
            l_suppliers := json_array_t();
            l_suppliers.append(l_supplier_node);

            l_item := json_object_t();
            l_item.put('item', p_item);
            l_item.put('dataLoadingDestination', 'RMS');
            l_item.put('supplier', l_suppliers);
            l_items.append(l_item);
        end;
    begin
        select json_value(l_payload, '$.SUPPLIER' returning number)
          into l_supplier
          from dual;

        append_item(request_style(p_action_request_id));

        for v in c_size_curve(l_payload) loop
            append_item(resolve_sku(l_payload, v.source_variant_ref, v.sku_id));
        end loop;

        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    -- A UDA's displayType, from master data.
    --
    -- MFCS rejects a uda row without displayType, and displayType decides which of
    -- udaValue / udaText / udaDate is read. Asking Office to send it would be
    -- asking them to restate something the tenant already publishes, so it is
    -- looked up from the definitions ie_mfcs_master_data.load_udas stores.
    --
    -- The fallbacks matter on a tenant whose UDA feed has not been refreshed. An
    -- explicit UDA_TYPE in the document wins, then master data, then the shape of
    -- the document row itself. Guessing beats sending nothing: a null displayType
    -- is a certain rejection, where a wrong guess is at least diagnosable.
    function uda_display_type(
        p_uda_id   in number,
        p_uda_type in varchar2,
        p_uda_text in varchar2,
        p_uda_date in varchar2
    ) return varchar2 is
        l_type varchar2(2);
    begin
        if p_uda_type is not null then
            return upper(p_uda_type);
        end if;

        begin
            select json_value(attributes, '$.displayType' returning varchar2(2))
              into l_type
              from ie_mfcs_ref_master_data
             where data_type = 'UDA'
               and data_code = to_char(p_uda_id)
               and parent_code = '~';
        exception
            when no_data_found then
                l_type := null;
        end;

        if l_type is not null then
            return l_type;
        elsif p_uda_date is not null then
            return 'DT';
        elsif p_uda_text is not null then
            return 'FF';
        else
            return 'LV';
        end if;
    end;

    -- The style's UDA rows. Built fresh per caller rather than shared, because
    -- json_array_t is a reference type: attaching one instance to several items
    -- would alias the same rows across the payload.
    function style_uda_array(p_payload in clob) return json_array_t is
        l_udas json_array_t := json_array_t();
        l_uda json_object_t;
        l_type varchar2(2);
    begin
        for u in c_style_udas(p_payload) loop
            l_type := uda_display_type(u.uda_id, u.uda_type, u.uda_text, u.uda_date);
            l_uda := json_object_t();
            l_uda.put('udaId', u.uda_id);
            l_uda.put('displayType', l_type);
            case l_type
                when 'FF' then l_uda.put('udaText', nvl(u.uda_text, u.uda_value));
                when 'DT' then l_uda.put('udaDate', nvl(u.uda_date, u.uda_value));
                else l_uda.put('udaValue', u.uda_value);
            end case;
            l_udas.append(l_uda);
        end loop;
        return l_udas;
    end;

    -- The envelope every style-attribute service shares: one entry per item,
    -- each carrying the same array under its own property name.
    --
    -- Returns collectionSize 0 when nothing was captured, which the orchestrator
    -- treats as nothing to send rather than calling the tenant with an empty
    -- array. That is what makes each of these genuinely optional.
    function attribute_request(
        p_action_request_id in varchar2,
        p_property          in varchar2,
        p_values            in json_array_t,
        -- Whether the children get their own copy. UDAs and seasons do; images do
        -- not, because MFCS cascades an image from the parent and then refuses the
        -- child's copy as a duplicate: "Same file name already exists for this
        -- item". Proven live 2026-09-01.
        p_include_children  in boolean default true
    ) return clob is
        l_payload clob := payload(p_action_request_id);
        l_style varchar2(30) := request_style(p_action_request_id);
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_item json_object_t;
        l_sku varchar2(30);
        l_values_clob clob;

        -- json_array_t is a reference type, so each item needs its own copy or
        -- they would all alias the same rows.
        procedure add(p_item in varchar2) is
        begin
            if p_item is null then
                return;
            end if;
            l_item := json_object_t();
            l_item.put('item', p_item);
            l_item.put('dataLoadingDestination', 'RMS');
            l_item.put(p_property, json_array_t.parse(l_values_clob));
            l_items.append(l_item);
        end;
    begin
        if p_values is null or p_values.get_size = 0 then
            l_root.put('collectionSize', 0);
            l_root.put('items', json_array_t());
            return l_root.to_clob;
        end if;

        l_values_clob := p_values.to_clob;
        add(l_style);
        if p_include_children then
            for v in c_size_curve(l_payload) loop
                l_sku := resolve_sku(l_payload, v.source_variant_ref, v.sku_id);
                add(l_sku);
            end loop;
        end if;

        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function item_season_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_arr json_array_t := json_array_t();
        l_row json_object_t;
    begin
        for v in c_style_seasons(l_payload) loop
            l_row := json_object_t();
            l_row.put('seasonId', v.season_id);
            l_row.put('phaseId', v.phase_id);
            if v.sequence_no is not null then
                l_row.put('sequenceNo', v.sequence_no);
            end if;
            l_arr.append(l_row);
        end loop;
        return attribute_request(p_action_request_id, 'season', l_arr);
    end;

    function item_image_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_arr json_array_t := json_array_t();
        l_row json_object_t;
    begin
        for v in c_style_images(l_payload) loop
            l_row := json_object_t();
            l_row.put('imageName', v.image_name);
            if v.image_address is not null then
                l_row.put('imageAddress', v.image_address);
            end if;
            if v.image_description is not null then
                l_row.put('imageDescription', v.image_description);
            end if;
            l_row.put('imageType', nvl(v.image_type,
                ie_mfcs_config.get_config('MFCS_IMAGE_TYPE', 'T')));
            l_row.put('primaryImageInd', nvl(upper(v.primary_yn), 'N'));
            if v.display_priority is not null then
                l_row.put('displayPriority', v.display_priority);
            end if;
            l_arr.append(l_row);
        end loop;
        -- Style only; see p_include_children.
        return attribute_request(p_action_request_id, 'image', l_arr, false);
    end;

    function item_hts_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_arr json_array_t := json_array_t();
        l_row json_object_t;
    begin
        for v in c_style_hts(l_payload) loop
            l_row := json_object_t();
            l_row.put('hts', v.hts);
            l_row.put('importCountry', v.import_country);
            -- Must be a country the item already has as a country of manufacture,
            -- or MFCS answers "This item does not have a Country Of Manufacture".
            -- CREATE_ITEM_COUNTRIES_OF_MANUFACTURE runs earlier in the graph and
            -- writes MFCS_MANUFACTURER_COUNTRY, so that is the default when the
            -- document does not name one. A document that does name one is sent as
            -- given: the tenant rejects a mismatch loudly, which is more useful
            -- than us silently overriding what the caller asked for.
            l_row.put('originCountry', nvl(v.origin_country,
                ie_mfcs_config.get_config('MFCS_MANUFACTURER_COUNTRY', 'VN')));
            l_row.put('effectFrom', v.effect_from);
            l_row.put('effectTo', v.effect_to);
            l_row.put('status', ie_mfcs_config.get_config('MFCS_HTS_STATUS', 'A'));
            l_arr.append(l_row);
        end loop;
        return attribute_request(p_action_request_id, 'hts', l_arr);
    end;

    function item_uda_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_style varchar2(30) := request_style(p_action_request_id);
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_item json_object_t;
        l_sku varchar2(30);
    begin
        -- The parent carries the style's UDAs as well as the children, since SKUs
        -- inherit them and the tenant is not known to cascade. Skipped only when
        -- the style number is not resolvable yet.
        if l_style is not null then
            l_item := json_object_t();
            l_item.put('item', l_style);
            l_item.put('dataLoadingDestination', 'RMS');
            l_item.put('uda', style_uda_array(l_payload));
            l_items.append(l_item);
        end if;

        for v in c_size_curve(l_payload) loop
            l_sku := resolve_sku(l_payload, v.source_variant_ref, v.sku_id);
            l_item := json_object_t();
            l_item.put('item', l_sku);
            l_item.put('dataLoadingDestination', 'RMS');
            -- An empty array when the document carries no STYLE_UDAS. MFCS accepts
            -- it and does nothing, which keeps the step explicitly logged and keeps
            -- documents written before STYLE_UDAS behaving exactly as they did.
            l_item.put('uda', style_uda_array(l_payload));
            l_items.append(l_item);
        end loop;

        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    -- Barcodes, as level-3 items under their SKU.
    --
    -- There is no reference-item service on this tenant - none in 323 spec paths -
    -- so a UPC is an item like any other, created through items/create. Three
    -- things are load-bearing and were each found the hard way, live:
    --
    --   itemNumberType must be EAN13. ITEM and an absent type both demand a
    --   9-character number, and UPC-A demands 12.
    --
    --   costZoneGroupId must be sent and must equal the parent's, or MFCS answers
    --   "Field cannot be modified. Field: COST_ZONE_GROUP_ID" - an error naming a
    --   field the request never contained.
    --
    --   status and itemSupplier are inherited from the parent, so they are not
    --   sent. The created record comes back approved with the parent's supplier
    --   already attached.
    function reference_item_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_style varchar2(30) := request_style(p_action_request_id);
        l_department number;
        l_class number;
        l_subclass number;
        l_source_ref varchar2(120);
        l_color varchar2(10);
        l_cost_zone_group_id number :=
            to_number(ie_mfcs_config.get_config('MFCS_COST_ZONE_GROUP_ID', '2000'));
        l_default_type varchar2(10) :=
            ie_mfcs_config.get_config('MFCS_UPC_ITEM_NUMBER_TYPE', 'EAN13');
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_item json_object_t;
        l_sku varchar2(30);
    begin
        select json_value(l_payload, '$.DEPARTMENT' returning number),
               json_value(l_payload, '$.CLASS' returning number),
               json_value(l_payload, '$.SUBCLASS' returning number),
               json_value(l_payload, '$.SOURCE_STYLE_REF' returning varchar2(120)),
               json_value(l_payload, '$.COLOUR' returning varchar2(10))
          into l_department, l_class, l_subclass, l_source_ref, l_color
          from dual;

        for u in c_sku_upcs(l_payload) loop
            l_sku := resolve_sku(l_payload, u.source_variant_ref, u.sku_id);
            l_item := json_object_t();
            l_item.put('item', u.upc);
            l_item.put('itemParent', l_sku);
            l_item.put('itemGrandparent', l_style);
            l_item.put('itemLevel', 3);
            l_item.put('tranLevel', 2);
            l_item.put('itemNumberType', nvl(u.upc_type, l_default_type));
            l_item.put('primaryReferenceItemInd', nvl(upper(u.primary_yn), 'N'));
            l_item.put('dataLoadingDestination', 'RMS');
            l_item.put('itemDescription',
                sku_description(l_payload, u.item_description, u.sku_size));
            l_item.put('shortDescription', substr(l_source_ref, 1, 120));
            l_item.put('dept', l_department);
            l_item.put('class', l_class);
            l_item.put('subclass', l_subclass);
            l_item.put('diff1', l_color);
            l_item.put('diff2', u.sku_size);
            l_item.put('sellableInd', 'Y');
            l_item.put('orderableInd', 'Y');
            l_item.put('merchandiseInd', 'Y');
            l_item.put('inventoryInd', 'Y');
            l_item.put('standardUom', 'EA');
            l_item.put('costZoneGroupId', l_cost_zone_group_id);
            l_items.append(l_item);
        end loop;

        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function item_location_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_item json_object_t;
        l_location json_object_t;
        l_locations json_array_t;
        l_delivery number;
        l_hierarchy_value number;
        l_hierarchy_level varchar2(2) :=
            ie_mfcs_config.get_config('MFCS_LOCATION_HIERARCHY_LEVEL', 'CH');
        l_store_order_multiple varchar2(1) :=
            ie_mfcs_config.get_config('MFCS_STORE_ORDER_MULTIPLE', 'E');
        l_taxable_ind varchar2(1) :=
            ie_mfcs_config.get_config('MFCS_TAXABLE_IND', 'Y');
        l_sku varchar2(30);
    begin
        select json_value(l_payload, '$.DELIVERY_LOC' returning number)
          into l_delivery from dual;
        -- DELIVERY_LOC is an Office PHYSICAL location (1927). At hierarchyLevel W
        -- MFCS wants the VIRTUAL warehouse (19271) and rejects the physical one
        -- with "Invalid Warehouse". Map it the same way the purchase order does,
        -- so item ranging and ordering cannot disagree about where the item goes.
        l_hierarchy_value := to_number(
            coalesce(
                case when l_delivery is not null
                     then virtual_location(l_delivery)
                end,
                to_char(l_delivery),
                ie_mfcs_config.get_config('MFCS_LOCATION_HIERARCHY_VALUE', '19271')
            ));
        for v in c_size_curve(l_payload) loop
            l_sku := resolve_sku(l_payload, v.source_variant_ref, v.sku_id);
            l_location := json_object_t();
            l_location.put('hierarchyValue', l_hierarchy_value);
            l_location.put('status', 'A');
            l_location.put('storeOrderMultiple', l_store_order_multiple);
            l_location.put('taxableInd', l_taxable_ind);
            l_locations := json_array_t();
            l_locations.append(l_location);

            l_item := json_object_t();
            l_item.put('item', l_sku);
            l_item.put('dataLoadingDestination', 'RMS');
            l_item.put('hierarchyLevel', l_hierarchy_level);
            l_item.put('locations', l_locations);
            l_items.append(l_item);
        end loop;
        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function item_approval_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_item json_object_t;
        l_store_order_multiple varchar2(1) :=
            ie_mfcs_config.get_config('MFCS_STORE_ORDER_MULTIPLE', 'E');
        l_source_ref varchar2(120);
        l_sku varchar2(30);
    begin
        select json_value(l_payload, '$.SOURCE_STYLE_REF' returning varchar2(120))
          into l_source_ref
          from dual;

        l_item := json_object_t();
        l_item.put('item', request_style(p_action_request_id));
        l_item.put('itemDescription', style_description(l_payload));
        l_item.put('shortDescription', substr(l_source_ref, 1, 120));
        l_item.put('status', 'A');
        l_item.put('approveInd', 'Y');
        l_item.put('storeOrderMultiple', l_store_order_multiple);
        l_item.put('dataLoadingDestination', 'RMS');
        l_items.append(l_item);
        -- Each child keeps the description it was created with. This step used to
        -- send SOURCE_STYLE_REF for every item, which quietly overwrote every SKU
        -- description with the style's - so a size that had been captured, sent
        -- and stored was lost at the last step of the run.
        for v in c_size_curve(l_payload) loop
            l_sku := resolve_sku(l_payload, v.source_variant_ref, v.sku_id);
            l_item := json_object_t();
            l_item.put('item', l_sku);
            l_item.put('itemDescription',
                sku_description(l_payload, v.item_description, v.sku_size));
            l_item.put('shortDescription', substr(l_source_ref, 1, 120));
            l_item.put('status', 'A');
            l_item.put('approveInd', 'Y');
            l_item.put('storeOrderMultiple', l_store_order_multiple);
            l_item.put('dataLoadingDestination', 'RMS');
            l_items.append(l_item);
        end loop;
        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function initial_retail_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_item json_object_t;
        l_retail number;
        l_sku varchar2(30);
    begin
        select json_value(l_payload, '$.RETAIL_PRICE' returning number) into l_retail from dual;
        for v in c_size_curve(l_payload) loop
            l_sku := resolve_sku(l_payload, v.source_variant_ref, v.sku_id);
            l_item := json_object_t();
            l_item.put('item', l_sku);
            l_item.put('originalRetail', l_retail);
            l_item.put('dataLoadingDestination', 'RMS');
            l_items.append(l_item);
        end loop;
        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function po_number_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_root json_object_t := json_object_t();
    begin
        l_root.put('supplier', number_value(l_payload, 'SUPPLIER'));
        l_root.put('quantity', 1);
        l_root.put('expiryDays', to_number(ie_mfcs_config.get_config('MFCS_ORDER_RESERVATION_DAYS_UNTIL_EXPIRY', '1')));
        return l_root.to_clob;
    end;

    function optional_string(
        p_payload in clob,
        p_name    in varchar2
    ) return varchar2 is
    begin
        return json_object_t.parse(p_payload).get_string(p_name);
    exception
        when others then
            return null;
    end;

    function optional_number(
        p_payload in clob,
        p_name    in varchar2
    ) return number is
    begin
        return json_object_t.parse(p_payload).get_number(p_name);
    exception
        when others then
            return null;
    end;

    function order_location(p_payload in clob) return number is
        l_delivery varchar2(30);
        l_location varchar2(30);
    begin
        l_delivery := to_char(optional_number(p_payload, 'DELIVERY_LOC'));
        if l_delivery is not null then
            l_location := virtual_location(l_delivery);
        else
            l_location := ie_mfcs_config.get_config('MFCS_ORDER_DEFAULT_LOCATION', null);
        end if;
        return to_number(l_location);
    end;

    function purchase_order_request(p_action_request_id in varchar2) return clob is
        l_payload clob := payload(p_action_request_id);
        l_root json_object_t := json_object_t();
        l_orders json_array_t := json_array_t();
        l_order json_object_t := json_object_t();
        l_details json_array_t := json_array_t();
        l_detail json_object_t;
        l_expenses json_array_t := json_array_t();
        l_expense json_object_t;
        l_sku varchar2(30);
        l_operation varchar2(30);
        l_order_location number := order_location(l_payload);
        l_location_type varchar2(1) := ie_mfcs_config.get_config('MFCS_ORDER_LOCATION_TYPE', 'W');
        l_written_date varchar2(10) := substr(coalesce(optional_string(l_payload, 'WRITTEN_DATE'), to_char(sysdate, 'YYYY-MM-DD')), 1, 10);
        l_import_country varchar2(3) := coalesce(
            optional_string(l_payload, 'IMPORT_COUNTRY'),
            ie_mfcs_config.get_config('MFCS_ORDER_DEFAULT_IMPORT_COUNTRY', string_value(l_payload, 'ORIGIN_COUNTRY'))
        );
        l_terms varchar2(15) := coalesce(optional_string(l_payload, 'TERMS'), ie_mfcs_config.get_config('MFCS_ORDER_DEFAULT_TERMS', null));
    begin
        select json_value(l_payload, '$.OPERATION_NAME' returning varchar2(30)) into l_operation from dual;
        l_order.put('orderNo', to_number(request_order(p_action_request_id)));
        l_order.put('supplier', number_value(l_payload, 'SUPPLIER'));
        l_order.put('currencyCode', string_value(l_payload, 'CURRENCY_CODE'));
        if l_terms is not null then
            l_order.put('terms', l_terms);
        end if;
        l_order.put('notBeforeDate', string_value(l_payload, 'NOT_BEFORE_DATE'));
        l_order.put('notAfterDate', string_value(l_payload, 'NOT_AFTER_DATE'));
        if optional_string(l_payload, 'OTB_EOW_DATE') is not null then
            l_order.put('otbEowDate', optional_string(l_payload, 'OTB_EOW_DATE'));
        end if;
        l_order.put('earliestShipDate', string_value(l_payload, 'EARLIEST_SHIP_DATE'));
        l_order.put('latestShipDate', string_value(l_payload, 'LATEST_SHIP_DATE'));
        l_order.put('dept', number_value(l_payload, 'DEPARTMENT'));
        l_order.put('status', ie_mfcs_config.get_config('MFCS_ORDER_STATUS', 'A'));
        l_order.put('exchangeRate', coalesce(optional_number(l_payload, 'ORDER_EXCHANGE_RATE'), 1));
        l_order.put('includeOnOrderInd', ie_mfcs_config.get_config('MFCS_INCLUDE_ON_ORDER_IND', 'Y'));
        l_order.put('writtenDate', l_written_date);
        l_order.put('origin', ie_mfcs_config.get_config('MFCS_ORDER_ORIGIN', '2'));
        l_order.put('ediPoInd', ie_mfcs_config.get_config('MFCS_EDI_PO_IND', 'N'));
        l_order.put('preMarkInd', ie_mfcs_config.get_config('MFCS_PRE_MARK_IND', 'N'));
        l_order.put('approvedBy', user_id(l_payload));
        l_order.put('commentDesc', coalesce(optional_string(l_payload, 'ORDER_AMEND_MSG'), optional_string(l_payload, 'SPECIAL_INSTRUCTION'), source_order_ref(l_payload)));
        l_order.put('dataLoadingDestination', 'RMS');
        l_order.put('importCountry', l_import_country);
        l_order.put('orderType', ie_mfcs_config.get_config('MFCS_ORDER_TYPE', 'N/B'));
        if optional_string(l_payload, 'PO_TYPE') is not null then
            l_order.put('purchaseOrderType', optional_string(l_payload, 'PO_TYPE'));
        end if;
        l_order.put('location', l_order_location);
        l_order.put('locationType', l_location_type);
        l_order.put('qualityControlInd', ie_mfcs_config.get_config('MFCS_QUALITY_CONTROL_IND', 'N'));
        l_order.put('freightTerms', ie_mfcs_config.get_config('MFCS_FREIGHT_TERMS', 'PREPAID'));

        for v in c_size_curve(l_payload) loop
            l_sku := resolve_sku(l_payload, v.source_variant_ref, v.sku_id);
            l_detail := json_object_t();
            l_detail.put('item', l_sku);
            l_detail.put('location', l_order_location);
            l_detail.put('locationType', l_location_type);
            l_detail.put('unitCost', number_value(l_payload, 'UNIT_COST'));
            l_detail.put('originCountry', string_value(l_payload, 'ORIGIN_COUNTRY'));
            l_detail.put('supplierPackSize', to_number(ie_mfcs_config.get_config('MFCS_SUPPLIER_PACK_SIZE', '1')));
            l_detail.put('quantityOrdered', v.sku_qty);
            l_detail.put('earliestShipDate', string_value(l_payload, 'EARLIEST_SHIP_DATE'));
            l_detail.put('latestShipDate', string_value(l_payload, 'LATEST_SHIP_DATE'));
            l_details.append(l_detail);

            -- Non-merchandise costs, one expense row per SKU per location. This is
            -- the ORDLOC_EXP equivalent: unit cost covers the merchandise, these
            -- cover freight, duty, handling and so on, and together they give
            -- landed cost. MFCS accepts them inside the order create, so they do
            -- not need a separate call.
            for e in (
                select component, calculation_basis, component_rate, component_currency,
                       per_count, per_count_uom, in_duty, in_expense, in_alc
                  from json_table(l_payload, '$.NON_MERCH_COSTS[*]'
                      columns
                          component          varchar2(30)  path '$.COMPONENT',
                          calculation_basis  varchar2(10)  path '$.CALCULATION_BASIS',
                          component_rate     number        path '$.RATE',
                          component_currency varchar2(10)  path '$.CURRENCY',
                          per_count          number        path '$.PER_COUNT',
                          per_count_uom      varchar2(10)  path '$.PER_COUNT_UOM',
                          in_duty            varchar2(1)   path '$.IN_DUTY',
                          in_expense         varchar2(1)   path '$.IN_EXPENSE',
                          in_alc             varchar2(1)   path '$.IN_ALC'
                  )
            ) loop
                l_expense := json_object_t();
                l_expense.put('item', l_sku);
                l_expense.put('location', l_order_location);
                l_expense.put('locationType', l_location_type);
                l_expense.put('component', e.component);
                l_expense.put('calculationBasis',
                    nvl(e.calculation_basis, ie_mfcs_config.get_config('MFCS_EXPENSE_CALC_BASIS', 'V')));
                l_expense.put('componentRate', e.component_rate);
                l_expense.put('componentCurrency',
                    nvl(e.component_currency, string_value(l_payload, 'CURRENCY_CODE')));
                if e.per_count is not null then
                    l_expense.put('perCount', e.per_count);
                    l_expense.put('perCountUom',
                        nvl(e.per_count_uom, ie_mfcs_config.get_config('MFCS_COST_UOM', 'EA')));
                end if;
                -- Nomination flags decide whether a component feeds duty, expense
                -- and actual landed cost. Defaulted rather than omitted, because
                -- omitting them changes what the cost is counted towards.
                l_expense.put('inDuty', nvl(e.in_duty, ie_mfcs_config.get_config('MFCS_EXPENSE_IN_DUTY', 'N')));
                l_expense.put('inExpense', nvl(e.in_expense, ie_mfcs_config.get_config('MFCS_EXPENSE_IN_EXPENSE', 'Y')));
                l_expense.put('inAlc', nvl(e.in_alc, ie_mfcs_config.get_config('MFCS_EXPENSE_IN_ALC', 'Y')));
                l_expenses.append(l_expense);
            end loop;
        end loop;
        l_order.put('details', l_details);
        if l_expenses.get_size > 0 then
            l_order.put('expenses', l_expenses);
        end if;
        l_orders.append(l_order);
        l_root.put('items', l_orders);
        return l_root.to_clob;
    end;

    -- Sourcing terms for a generated child. The document wins where it names
    -- them, because that is the commercial decision the request is carrying. The
    -- parent style is the fallback, for the order-shaped documents that name a
    -- style and say nothing about sourcing at all.
    procedure generated_sourcing_context(
        p_action_request_id in varchar2,
        p_plan              in t_child_plan,
        o_supplier          out number,
        o_cost              out number,
        o_country           out varchar2
    ) is
        l_payload clob := payload(p_action_request_id);
    begin
        select json_value(l_payload, '$.SUPPLIER' returning number),
               json_value(l_payload, '$.UNIT_COST' returning number),
               json_value(l_payload, '$.ORIGIN_COUNTRY' returning varchar2(3))
          into o_supplier, o_cost, o_country
          from dual;

        o_supplier := coalesce(o_supplier, p_plan.supplier);
        o_cost := coalesce(o_cost, p_plan.unit_cost);
        o_country := coalesce(o_country, p_plan.origin_country);

        -- Approval requires sourcing, so a child created without it would be
        -- stranded in worksheet status. Better to say so before anything has
        -- been created.
        if o_supplier is null or o_country is null then
            raise_application_error(-20964,
                'Cannot create children for style ' || p_plan.style
                || ': neither the request nor the style itself gives a supplier and origin '
                || 'country, and MFCS will not approve an item that has no sourcing.');
        end if;
    end;

    function generated_child_create_request(
        p_action_request_id in varchar2,
        p_plan              in t_child_plan
    ) return clob is
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_item json_object_t;
        -- Everything structural comes from the parent as the tenant holds it,
        -- not from configuration. A child that disagreed with its parent about
        -- the hierarchy would be rejected; one that agreed with our defaults
        -- instead of with its parent would be worse, because it would be
        -- accepted and wrong. Configuration only fills what the read did not
        -- carry.
        l_cost_zone_group_id number := nvl(p_plan.cost_zone_group_id,
            to_number(ie_mfcs_config.get_config('MFCS_COST_ZONE_GROUP_ID', '2000')));
        l_store_order_multiple varchar2(1) := nvl(p_plan.store_order_multiple,
            ie_mfcs_config.get_config('MFCS_STORE_ORDER_MULTIPLE', 'E'));
        l_standard_uom varchar2(10) := nvl(p_plan.standard_uom, 'EA');
        l_child t_generated_child;
    begin
        for i in 1 .. p_plan.children.count loop
            l_child := p_plan.children(i);
            l_item := json_object_t();
            l_item.put('item', l_child.item);
            l_item.put('itemParent', p_plan.style);
            l_item.put('itemDescription',
                substr(trim(p_plan.item_description || ' ' || l_child.sku_size
                    || ' ' || l_child.sku_width), 1, 250));
            l_item.put('shortDescription',
                substr(nvl(p_plan.short_description, p_plan.item_description), 1, 120));
            l_item.put('dataLoadingDestination', 'RMS');
            l_item.put('itemNumberType', 'ITEM');
            l_item.put('itemLevel', 2);
            l_item.put('tranLevel', 2);
            l_item.put('dept', p_plan.dept);
            l_item.put('class', p_plan.class);
            l_item.put('subclass', p_plan.subclass);
            l_item.put('status', 'W');
            l_item.put('approveInd', 'N');
            l_item.put('standardUom', l_standard_uom);
            l_item.put('merchandiseInd', 'Y');
            l_item.put('inventoryInd', 'Y');
            l_item.put('sellableInd', 'Y');
            l_item.put('orderableInd', 'Y');
            l_item.put('storeOrderMultiple', l_store_order_multiple);
            if p_plan.original_retail is not null then
                l_item.put('originalRetail', p_plan.original_retail);
            end if;
            l_item.put('costZoneGroupId', l_cost_zone_group_id);
            -- The diffs are already resolved. The plan carries the values the
            -- gap analysis compared against, so a child cannot be created on a
            -- different combination from the one found missing.
            l_item.put('diff1', l_child.colour_diff);
            l_item.put('diff1Type', 'C');
            l_item.put('diff2', l_child.size_diff);
            l_item.put('diff2Type', 'S');
            l_items.append(l_item);
        end loop;

        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function generated_child_sourcing_request(
        p_action_request_id in varchar2,
        p_plan              in t_child_plan
    ) return clob is
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_supplier number;
        l_cost number;
        l_country varchar2(3);
    begin
        generated_sourcing_context(p_action_request_id, p_plan, l_supplier, l_cost, l_country);

        for i in 1 .. p_plan.children.count loop
            l_items.append(supplier_payload(p_plan.children(i).item, l_supplier, l_cost, l_country));
        end loop;

        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function generated_child_com_request(
        p_action_request_id in varchar2,
        p_plan              in t_child_plan
    ) return clob is
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_item json_object_t;
        l_supplier_node json_object_t;
        l_manufacture_node json_object_t;
        l_suppliers json_array_t;
        l_manufacturers json_array_t;
        l_supplier number;
        l_cost number;
        l_country varchar2(3);
        l_manufacturer_country varchar2(3) :=
            ie_mfcs_config.get_config('MFCS_MANUFACTURER_COUNTRY', 'VN');
    begin
        generated_sourcing_context(p_action_request_id, p_plan, l_supplier, l_cost, l_country);

        -- Only the new children. The parent already carries a country of
        -- manufacture, or it could not have been approved in the first place.
        for i in 1 .. p_plan.children.count loop
            l_manufacture_node := json_object_t();
            l_manufacture_node.put('manufacturerCountry', l_manufacturer_country);
            l_manufacture_node.put('primaryManufacturerCountryInd', 'Y');
            l_manufacturers := json_array_t();
            l_manufacturers.append(l_manufacture_node);

            l_supplier_node := json_object_t();
            l_supplier_node.put('supplier', l_supplier);
            l_supplier_node.put('countryOfManufacture', l_manufacturers);
            l_suppliers := json_array_t();
            l_suppliers.append(l_supplier_node);

            l_item := json_object_t();
            l_item.put('item', p_plan.children(i).item);
            l_item.put('dataLoadingDestination', 'RMS');
            l_item.put('supplier', l_suppliers);
            l_items.append(l_item);
        end loop;

        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function generated_child_approval_request(
        p_action_request_id in varchar2,
        p_plan              in t_child_plan
    ) return clob is
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_item json_object_t;
        l_store_order_multiple varchar2(1) := nvl(p_plan.store_order_multiple,
            ie_mfcs_config.get_config('MFCS_STORE_ORDER_MULTIPLE', 'E'));

        procedure append_approval(p_item in varchar2, p_description in varchar2) is
        begin
            l_item := json_object_t();
            l_item.put('item', p_item);
            l_item.put('itemDescription', substr(p_description, 1, 250));
            l_item.put('shortDescription',
                substr(nvl(p_plan.short_description, p_description), 1, 120));
            l_item.put('status', 'A');
            l_item.put('approveInd', 'Y');
            l_item.put('storeOrderMultiple', l_store_order_multiple);
            l_item.put('dataLoadingDestination', 'RMS');
            l_items.append(l_item);
        end;
    begin
        -- The parent goes in every time, not only when a read says it is
        -- unapproved. Deciding from observed status would be a partial update,
        -- which this layer does not do; re-approving an approved item costs a
        -- field in a payload that is being sent regardless.
        append_approval(p_plan.style, p_plan.item_description);

        for i in 1 .. p_plan.children.count loop
            append_approval(p_plan.children(i).item,
                trim(p_plan.item_description || ' ' || p_plan.children(i).sku_size
                    || ' ' || p_plan.children(i).sku_width));
        end loop;

        l_root.put('collectionSize', l_items.get_size);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    -- Shared line shape for details create/update. Everything except item and
    -- quantity is order-level on this integration: one style, one supplier,
    -- one delivery location per document.
    function order_line_node(
        p_plan in t_order_line_plan,
        p_line in t_order_line
    ) return json_object_t is
        l_line json_object_t := json_object_t();
    begin
        l_line.put('item', p_line.item);
        l_line.put('location', p_plan.location);
        l_line.put('locationType', p_plan.location_type);
        l_line.put('unitCost', p_plan.unit_cost);
        l_line.put('originCountry', p_plan.origin_country);
        l_line.put('supplierPackSize', p_plan.supplier_pack_size);
        l_line.put('quantityOrdered', p_line.quantity);
        -- Reducing a line needs a reason - B, "Buyer Cancelled" - distinct from a
        -- full-line cancellation's S, "Colour/Location Switched" (both from the
        -- tenant's own code type ORCA). quantityOrdered is authoritative;
        -- quantityCancelled is deliberately NOT sent. It proved to be
        -- cumulative-absolute on this tenant: re-sending a line's existing
        -- cancelled quantity is a silent no-op, which left a cancel half-applied
        -- the first time this ran live.
        if p_line.prev_quantity is not null and p_line.quantity < p_line.prev_quantity then
            l_line.put('cancelCode', ie_mfcs_config.get_config('MFCS_ORDER_REDUCE_CANCEL_CODE', 'B'));
        end if;
        l_line.put('earliestShipDate', p_plan.earliest_ship_date);
        l_line.put('latestShipDate', p_plan.latest_ship_date);
        return l_line;
    end;

    function order_details_envelope(
        p_plan    in t_order_line_plan,
        p_details in json_array_t
    ) return clob is
        l_root json_object_t := json_object_t();
        l_items json_array_t := json_array_t();
        l_order json_object_t := json_object_t();
    begin
        l_order.put('orderNo', to_number(p_plan.order_no));
        l_order.put('dataLoadingDestination', 'RMS');
        l_order.put('details', p_details);
        l_items.append(l_order);
        l_root.put('items', l_items);
        return l_root.to_clob;
    end;

    function order_details_update_request(p_plan in t_order_line_plan) return clob is
        l_details json_array_t := json_array_t();
    begin
        for i in 1 .. p_plan.updates.count loop
            l_details.append(order_line_node(p_plan, p_plan.updates(i)));
        end loop;
        return order_details_envelope(p_plan, l_details);
    end;

    function order_details_create_request(p_plan in t_order_line_plan) return clob is
        l_details json_array_t := json_array_t();
    begin
        for i in 1 .. p_plan.creates.count loop
            l_details.append(order_line_node(p_plan, p_plan.creates(i)));
        end loop;
        return order_details_envelope(p_plan, l_details);
    end;

    function order_details_cancel_request(p_plan in t_order_line_plan) return clob is
        l_details json_array_t := json_array_t();
        l_line json_object_t;
        l_cancel_code varchar2(6) := ie_mfcs_config.get_config('MFCS_ORDER_CANCEL_CODE', 'S');
    begin
        -- A full cancellation drives quantityOrdered to zero and says why. Not
        -- quantityCancelled: that field is cumulative-absolute on this tenant,
        -- so a line with a prior partial cancellation ignores a repeat of its
        -- existing cancelled quantity - proven live when one of three identical
        -- cancels silently did nothing. quantityOrdered:0 zeroes the line
        -- regardless of its history.
        for i in 1 .. p_plan.cancels.count loop
            l_line := json_object_t();
            l_line.put('item', p_plan.cancels(i).item);
            l_line.put('location', p_plan.location);
            l_line.put('locationType', p_plan.location_type);
            l_line.put('quantityOrdered', 0);
            l_line.put('cancelInd', 'Y');
            l_line.put('cancelCode', l_cancel_code);
            l_details.append(l_line);
        end loop;
        return order_details_envelope(p_plan, l_details);
    end;

    function build_request(
        p_action_request_id in varchar2,
        p_mapper_name       in varchar2
    ) return clob is
    begin
        case p_mapper_name
            when 'build_item_number_request' then return item_number_request(p_action_request_id);
            when 'build_parent_item_create_request' then return parent_item_create_request(p_action_request_id);
            when 'build_child_item_create_request' then return child_item_create_request(p_action_request_id);
            when 'build_item_create_request' then return item_create_request(p_action_request_id);
            when 'build_parent_item_sourcing_request' then return parent_item_sourcing_request(p_action_request_id);
            when 'build_child_item_sourcing_request' then return child_item_sourcing_request(p_action_request_id);
            when 'build_item_sourcing_request' then return item_sourcing_request(p_action_request_id);
            when 'build_item_country_of_manufacture_request' then return item_country_of_manufacture_request(p_action_request_id);
            when 'build_item_uda_request' then return item_uda_request(p_action_request_id);
            when 'build_reference_item_request' then return reference_item_request(p_action_request_id);
            when 'build_item_season_request' then return item_season_request(p_action_request_id);
            when 'build_item_image_request' then return item_image_request(p_action_request_id);
            when 'build_item_hts_request' then return item_hts_request(p_action_request_id);
            when 'build_item_location_request' then return item_location_request(p_action_request_id);
            when 'build_item_approval_request' then return item_approval_request(p_action_request_id);
            when 'build_initial_retail_request' then return initial_retail_request(p_action_request_id);
            when 'build_po_number_request' then return po_number_request(p_action_request_id);
            when 'build_purchase_order_request' then return purchase_order_request(p_action_request_id);
            else raise_application_error(-20820, 'Unsupported public mapper: ' || p_mapper_name);
        end case;
    end;
end ie_mfcs_payload;
/

-- ==== 20_packages/07_ie_mfcs_client.sql

-- Outbound MFCS calls: credentials, HTTP, attempt journalling.
--
-- The only package that resolves a credential or makes an outbound call.
-- Keep it that way: a second HTTP path is how a stale token once survived in
-- one code path and not another.
--
-- Credentials live in the APEX credential store, not in this schema. The
-- client id and secret are entered once, as a Web Credential in the workspace,
-- and are then unreadable: no view returns either, and they are excluded from
-- application exports. apex_web_service fetches the bearer token, caches it in
-- the database and refetches it on expiry, so nothing here holds a token.
--
-- There is one mode. The original layer also had STATIC_BEARER - a token
-- pasted by hand into a SECRET table, which expired hourly - kept as a
-- fallback while the credential store was new. It was deliberately not
-- carried into RDS: a table holding a plain secret is exactly what the
-- credential store replaced, and nothing here should start life with one.
--
-- That last point is not only about secrecy. This package used to cache the
-- token in a package global while the comment here claimed it did not, and
-- the rule exists for a reason: ORDS pools sessions, so a cached token
-- outlives the request that fetched it and survives a change of tenant -
-- which surfaces as the 403 documented in CLAUDE.md rather than as anything
-- that names a token.
--
-- Failure classification matters more than it looks. An HTTP error with a
-- readable body is a failure (-20950); HTTP 503 and the tenant's nightly
-- batch refusal are unavailability (-20951); a transport error after the
-- request may have been sent is an unknown outcome (-20952), resolved later
-- by ie_mfcs_recovery - never assume a send that errored did not land.

create or replace package ie_mfcs_client authid definer as
    e_downstream_failure exception;
    pragma exception_init(e_downstream_failure, -20950);

    e_downstream_unavailable exception;
    pragma exception_init(e_downstream_unavailable, -20951);

    e_outcome_unknown exception;
    pragma exception_init(e_outcome_unknown, -20952);

    -- Authenticated GET against the MFCS tenant. Exposed so the master-data and
    -- browse packages share one implementation of credential handling and headers
    -- rather than each keeping a copy of it.
    function get_json(
        p_path   in varchar2,
        o_status out number
    ) return clob;

    -- Says whether the credential is registered and what it points at. Never
    -- returns the id, the secret or a token - none of them can be read back.
    function token_status return clob;

    function call_service(
        p_action_request_id in varchar2,
        p_step_code         in varchar2,
        p_http_method       in varchar2,
        p_endpoint_key      in varchar2,
        p_request_payload   in clob,
        p_user_id           in varchar2
    ) return clob;

    function correlation_status(
        p_action_request_id in varchar2,
        p_correlation_id    in varchar2
    ) return clob;
end ie_mfcs_client;
/

create or replace package body ie_mfcs_client as

    -- No wallet arguments anywhere in this package. The original read a wallet
    -- path, password and host from config, never seeded any of them, and so
    -- always passed nulls; on Autonomous Database the built-in certificate store
    -- is what a null wallet means, which is the behaviour wanted.

    function credential_static_id return varchar2 is
    begin
        return ie_mfcs_config.get_config('MFCS_CREDENTIAL_STATIC_ID', 'MFCS_OAUTH');
    end;

    function token_url return varchar2 is
    begin
        return ie_mfcs_config.get_config('MFCS_TOKEN_URL');
    end;

    function oauth_scope return varchar2 is
    begin
        return ie_mfcs_config.get_config('MFCS_SCOPE');
    end;

    function workspace return varchar2 is
    begin
        return ie_mfcs_config.get_config('MFCS_APEX_WORKSPACE', 'MFCS');
    end;

    -- An APEX credential is workspace-scoped, and PL/SQL invoked through ORDS is
    -- not inside an APEX session, so the workspace has to be named before the
    -- credential can be resolved. Without this the call goes out with no
    -- Authorization header at all and MFCS answers 401 - a failure that looks
    -- exactly like a bad secret and is not one.
    procedure ensure_workspace is
    begin
        apex_util.set_workspace(p_workspace => workspace);
    end;

    -- Every outbound call goes through here, so that no call can be made
    -- without the workspace named and the credential attached. apex_web_service
    -- sets Authorization itself from the credential; setting it in the headers
    -- as well would win and defeat the point.
    function make_request(
        p_url         in varchar2,
        p_http_method in varchar2,
        p_body        in clob default null
    ) return clob is
    begin
        ensure_workspace;
        return apex_web_service.make_rest_request(
            p_url => p_url,
            p_http_method => p_http_method,
            p_body => p_body,
            p_transfer_timeout => to_number(ie_mfcs_config.get_config('HTTP_TRANSFER_TIMEOUT_SECONDS', '45')),
            p_credential_static_id => credential_static_id,
            p_token_url => token_url,
            p_oauth_scope => oauth_scope
        );
    end;

    function get_json(
        p_path   in varchar2,
        o_status out number
    ) return clob is
        l_response clob;
    begin
        apex_web_service.g_request_headers.delete;
        apex_web_service.g_request_headers(1).name := 'Accept';
        apex_web_service.g_request_headers(1).value := 'application/json';
        apex_web_service.g_request_headers(2).name := 'X-Correlation-ID';
        apex_web_service.g_request_headers(2).value := lower(rawtohex(sys_guid()));

        l_response := make_request(
            rtrim(ie_mfcs_config.get_config('MFCS_BASE_URL'), '/') || p_path, 'GET');
        o_status := apex_web_service.g_status_code;
        return l_response;
    end;

    -- There is no token here to decode: apex_web_service holds it, and
    -- deliberately exposes neither it nor the secret behind it. Report what can
    -- be known - that the credential exists and what it points at - rather than
    -- nothing, since this is the first thing checked when calls start failing.
    function token_status return clob is
        l_root json_object_t := json_object_t();
        l_ref varchar2(200) := credential_static_id;
        l_count number;
    begin
        l_root.put('mode', 'OAUTH_CLIENT_CREDENTIALS');
        l_root.put('workspace', workspace);
        l_root.put('credentialStaticId', l_ref);
        l_root.put('tokenUrl', token_url);
        l_root.put('scope', oauth_scope);

        begin
            ensure_workspace;
            select count(*) into l_count
              from apex_workspace_credentials
             where static_id = l_ref;
        exception
            when others then
                l_count := 0;
                l_root.put('error', substr(sqlerrm, 1, 400));
        end;

        l_root.put('present', l_count > 0);
        if l_count > 0 then
            -- Not 'valid'. It says a credential is registered, not that the id
            -- and secret in it are right - only a call can show that.
            l_root.put('expired', false);
            l_root.put('message',
                'Credential ' || l_ref || ' is registered. '
                || 'The bearer token is fetched and refreshed automatically.');
        else
            l_root.put('expired', true);
            l_root.put('message',
                'No APEX credential ' || l_ref || ' in workspace ' || workspace
                || '. Create it under Workspace Utilities > Web Credentials: '
                || 'OAuth2 Client Credentials, static id ' || l_ref || '.');
        end if;
        return l_root.to_clob;
    end;

    function call_service(
        p_action_request_id in varchar2,
        p_step_code         in varchar2,
        p_http_method       in varchar2,
        p_endpoint_key      in varchar2,
        p_request_payload   in clob,
        p_user_id           in varchar2
    ) return clob is
        l_endpoint_path varchar2(1000);
        l_endpoint varchar2(1000);
        l_base_url varchar2(1000);
        l_attempt_id number;
        l_correlation_id varchar2(80);
        l_response clob;
        l_http_status number;
        l_order_no varchar2(30);
    begin
        l_base_url := ie_mfcs_config.get_config('MFCS_BASE_URL');
        l_endpoint_path := ie_mfcs_config.get_config(p_endpoint_key);

        if instr(l_endpoint_path, '{orderNo}') > 0 then
            select order_no
              into l_order_no
              from ie_mfcs_prd_request
             where action_request_id = p_action_request_id;
            l_endpoint_path := replace(l_endpoint_path, '{orderNo}', l_order_no);
        end if;

        l_endpoint := rtrim(l_base_url, '/') || l_endpoint_path;

        ie_mfcs_step.begin_attempt(
            p_action_request_id => p_action_request_id,
            p_step_code => p_step_code,
            p_http_method => p_http_method,
            p_endpoint => l_endpoint,
            p_request_payload => p_request_payload,
            o_attempt_id => l_attempt_id,
            o_correlation_id => l_correlation_id
        );

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'HTTP_CALL_PREPARED',
            p_step_code => p_step_code,
            p_attempt_id => l_attempt_id,
            p_message => 'Prepared outbound MFCS call.',
            p_detail_payload => '{"endpointKey":"' || ie_mfcs_event.escape_json(p_endpoint_key)
                || '","endpoint":"' || ie_mfcs_event.escape_json(l_endpoint)
                || '","method":"' || ie_mfcs_event.escape_json(p_http_method)
                || '","requestBytes":' || coalesce(to_char(dbms_lob.getlength(p_request_payload)), '0') || '}'
        );

        apex_web_service.g_request_headers.delete;
        apex_web_service.g_request_headers(1).name := 'Accept';
        apex_web_service.g_request_headers(1).value := 'application/json';
        apex_web_service.g_request_headers(2).name := 'Content-Type';
        apex_web_service.g_request_headers(2).value := 'application/json';
        apex_web_service.g_request_headers(3).name := 'X-Correlation-ID';
        apex_web_service.g_request_headers(3).value := l_correlation_id;
        apex_web_service.g_request_headers(4).name := 'X-Client-Principal-User';
        apex_web_service.g_request_headers(4).value := p_user_id;

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'HTTP_CALL_START',
            p_step_code => p_step_code,
            p_attempt_id => l_attempt_id,
            p_message => 'Calling remote MFCS endpoint.',
            p_detail_payload => '{"endpointKey":"' || ie_mfcs_event.escape_json(p_endpoint_key)
                || '","endpoint":"' || ie_mfcs_event.escape_json(l_endpoint)
                || '","timeoutSeconds":' || ie_mfcs_config.get_config('HTTP_TRANSFER_TIMEOUT_SECONDS', '45') || '}'
        );

        l_response := make_request(l_endpoint, p_http_method, p_request_payload);
        l_http_status := apex_web_service.g_status_code;

        ie_mfcs_event.log_event(
            p_action_request_id => p_action_request_id,
            p_event_phase => 'HTTP_CALL_RESPONSE',
            p_step_code => p_step_code,
            p_attempt_id => l_attempt_id,
            p_event_level => case when l_http_status between 200 and 299 then 'INFO' else 'ERROR' end,
            p_message => 'Remote MFCS endpoint returned.',
            p_detail_payload => '{"httpStatus":' || coalesce(to_char(l_http_status), 'null')
                || ',"responseBytes":' || coalesce(to_char(dbms_lob.getlength(l_response)), '0') || '}'
        );

        if l_http_status between 200 and 299 then
            ie_mfcs_step.complete_attempt(l_attempt_id, 'SUCCEEDED', l_http_status, l_response);
            return l_response;
        elsif l_http_status = 503 then
            ie_mfcs_step.complete_attempt(l_attempt_id, 'FAILED', l_http_status, l_response);
            raise_application_error(-20951, 'MFCS service unavailable at ' || p_endpoint_key);
        elsif instr(lower(dbms_lob.substr(l_response, 4000, 1)), 'batch running indicator is on') > 0 then
            -- The tenant's nightly batch. It arrives as a plain HTTP 400 with a
            -- business message, so without this it reads as a rejected payload and
            -- sends you looking for a bug in the request. It is the same condition
            -- BATCH_WINDOW_ACTIVE_YN describes, except the tenant is saying so
            -- itself, which beats a flag somebody has to remember to set.
            ie_mfcs_step.complete_attempt(l_attempt_id, 'FAILED', l_http_status, l_response);
            raise_application_error(-20951,
                'MFCS is in its nightly batch window and is refusing writes. Retry afterwards.');
        else
            ie_mfcs_step.complete_attempt(l_attempt_id, 'FAILED', l_http_status, l_response);
            raise_application_error(-20950, 'MFCS returned HTTP ' || l_http_status || ' at ' || p_endpoint_key);
        end if;
    exception
        when others then
            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'HTTP_CALL_EXCEPTION',
                p_step_code => p_step_code,
                p_attempt_id => l_attempt_id,
                p_event_level => 'ERROR',
                p_message => substr(sqlerrm, 1, 1000),
                p_detail_payload => '{"sqlcode":' || sqlcode
                    || ',"endpointKey":"' || ie_mfcs_event.escape_json(p_endpoint_key) || '"}'
            );

            if sqlcode in (-20950, -20951, -20952) then
                raise;
            end if;

            -- A transport failure has an *unknown* outcome, not a failed one.
            -- Learned the expensive way: ORA-29273 was classified FAILED, but MFCS
            -- had in fact created the purchase order. The resume then replayed the
            -- create and was told the order number already existed - a reserved
            -- number burned for nothing, and a request stuck at PARTIALLY_COMPLETED
            -- while the order it claimed to have failed to place sat in the tenant.
            --
            -- Classify on SQLCODE, not on the wording of the message. The old test
            -- matched only messages containing "timeout", which ORA-29273 does not.
            -- Codes that never landed resolve to NO_RECORD and the step simply runs
            -- again, so treating a connection error as unknown costs nothing.
            if sqlcode in (-29273,   -- UTL_HTTP: HTTP request failed
                           -29276,   -- UTL_HTTP: transfer timeout
                           -29259,   -- UTL_HTTP: end-of-input reached
                           -12535,   -- TNS: operation timed out
                           -12570)   -- TNS: packet reader failure
               or instr(lower(sqlerrm), 'timeout') > 0 then
                ie_mfcs_step.complete_attempt(l_attempt_id, 'OUTCOME_UNKNOWN', null, '{"ERROR":"' || replace(sqlerrm, '"', '\"') || '"}');
                raise_application_error(-20952,
                    'MFCS transport failed after the request was sent; outcome unknown. ' || sqlerrm);
            end if;

            if l_attempt_id is not null then
                ie_mfcs_step.complete_attempt(l_attempt_id, 'FAILED', null, '{"ERROR":"' || replace(sqlerrm, '"', '\"') || '"}');
            end if;
            raise_application_error(-20950, sqlerrm);
    end;

    -- Two defects in the original, and together they were dangerous.
    --
    -- It was the one call that bypassed the credential: it set 'Bearer ' || the
    -- static token by hand and passed no credential arguments, so in OAuth mode
    -- it sent an empty bearer and was always answered 401. Routing it through
    -- make_request fixes that, and is the reason make_request exists.
    --
    -- And it returned whatever came back regardless of status. ie_mfcs_recovery
    -- reads a body with no "count" as NO_RECORD and puts the step back to
    -- PENDING, so a 401 - or any failed lookup - re-ran a write that may well
    -- have landed: the duplicate this whole recovery path exists to prevent.
    -- A lookup that did not answer is not evidence that nothing happened, so it
    -- now reports UNKNOWN, which recovery sends to MANUAL_REVIEW.
    function correlation_status(
        p_action_request_id in varchar2,
        p_correlation_id    in varchar2
    ) return clob is
        l_endpoint varchar2(1000);
        l_response clob;
        l_http_status number;
    begin
        l_endpoint := rtrim(ie_mfcs_config.get_config('MFCS_BASE_URL'), '/')
            || ie_mfcs_config.get_config('ENDPOINT.REST_SERVICE_STATUS')
            || '?xCorrelationId=' || p_correlation_id
            || '&includePayload=Y';

        apex_web_service.g_request_headers.delete;
        apex_web_service.g_request_headers(1).name := 'Accept';
        apex_web_service.g_request_headers(1).value := 'application/json';

        l_response := make_request(l_endpoint, 'GET');
        l_http_status := apex_web_service.g_status_code;

        if l_http_status not between 200 and 299 then
            ie_mfcs_event.log_event(
                p_action_request_id => p_action_request_id,
                p_event_phase => 'CORRELATION_LOOKUP_FAILED',
                p_event_level => 'ERROR',
                p_message => 'Operation-status lookup answered HTTP ' || l_http_status
                    || '; the outcome stays unknown.',
                p_detail_payload => '{"correlationId":"' || ie_mfcs_event.escape_json(p_correlation_id)
                    || '","httpStatus":' || coalesce(to_char(l_http_status), 'null') || '}'
            );
            return '{"status":"UNKNOWN","httpStatus":' || coalesce(to_char(l_http_status), 'null') || '}';
        end if;

        return l_response;
    end;
end ie_mfcs_client;
/

